    (321, 2, '의사결정 장애요소', '문제의 표현 방식에 따라 동일한 사건에 대한 판단이나 선택이 달라지는 현상은?', '고정관념', '편향된 생각', '프레이밍 효과(Framing Effect)', '생존자 편향', 3, '프레이밍 효과는 표현 방식에 따라 판단·선택이 달라지는 현상이다.', 81, 'concept'),
    (322, 2, '의사결정 장애요소', '문제의 표현 방식에 따라 동일한 사건에 대한 판단이나 선택이 달라지는 현상은?', '편향된 생각', '프레이밍 효과(Framing Effect)', '생존자 편향', '고정관념', 2, '프레이밍 효과는 표현 방식에 따라 판단·선택이 달라지는 현상이다.', 81, 'concept'),
    (323, 2, '의사결정 장애요소', '다음 중 문제의 표현 방식에 따라 동일한 사건에 대한 판단이나 선택이 달라지는 현상은?', '프레이밍 효과(Framing Effect)', '생존자 편향', '고정관념', '편향된 생각', 1, '프레이밍 효과는 표현 방식에 따라 판단·선택이 달라지는 현상이다.', 81, 'concept'),
    (324, 2, '의사결정 장애요소', '보기 중에서 문제의 표현 방식에 따라 동일한 사건에 대한 판단이나 선택이 달라지는 현상은?', '생존자 편향', '프레이밍 효과(Framing Effect)', '편향된 생각', '고정관념', 2, '프레이밍 효과는 표현 방식에 따라 판단·선택이 달라지는 현상이다.', 81, 'concept'),
    (325, 2, '분석 방법론', '분석 방법론의 구성 요소에 해당하지 않는 것은?', '절차(Procedure)', '방법(Methods)', '도구와 기법', '예산 승인 규정', 4, '분석 방법론은 절차, 방법, 도구와 기법, 템플릿과 산출물로 구성된다.', 82, 'concept'),
