CBT_ROWS = [
    (1, 1, '빅데이터 개념', '다음 중 빅데이터 분석에 경제성을 제공해 준 결정적인 기술로 가장 적절한 것은?', '텍스트 마이닝', '클라우드 컴퓨팅', '저장장치 비용의 지속적인 하락', '스마트폰의 급속한 확산', 2, '클라우드 컴퓨팅은 맵리듀스와 같은 병렬분산처리 기법을 통해 거대 규모 데이터의 신속한 처리 비용을 급격히 하락시켜 빅데이터 분석의 경제성을 획기적으로 개선하였다.', 100001, 'cbt'),
    (2, 1, '빅데이터 가치', '다음 중 빅데이터의 가치 산정이 어려운 이유를 나타내는 사례로 가장 부적절한 것은?', '구글 검색에서 나타나는 것과 같은 데이터의 반복적 재사용', '전기차 배터리 정보를 충전소 최적지 선정과 같은 2차적 목적에 활용', '독자의 전자책 독서 순서 정보가 저자의 글쓰기 방식에 영향을 주는 것', '은행 대출심사 알고리즘 작동 원리 이해의 어려움', 4, '가치 산정을 어렵게 만드는 요인은 데이터의 재사용, 2차적 목적 활용, 창조적 방식의 새로운 가치 창출이다. 대출심사 알고리즘 이해의 어려움은 알고리즈미스트가 필요한 이유이지 가치 산정이 어려운 이유가 아니다.', 100002, 'cbt'),
    (3, 1, '빅데이터 분석특성', '다음 중 빅데이터 분석의 특성에 대한 설명 중 가장 부적절한 것은?', '더 많은 정보가 더 많은 가치를 창출할 수 있는 것은 아니다.', '비즈니스의 핵심에 대해 보다 객관적이고 종합적인 통찰력을 줄 수 있는 데이터를 찾는 것이 중요하다.', '빅데이터 과제와 관련된 주된 걸림돌은 비용이 아니다.', '데이터의 크기가 커질수록 분석을 많이 사용하는 것이 중요해진다.', 4, '데이터의 크기가 커진다고 분석을 많이 사용하는 것이 중요해지는 것은 아니다. 데이터의 성격과 얻고자 하는 가치에 적합한 분석을 사용하는 것이 중요하다.', 100003, 'cbt'),
    (4, 1, '가치창출', '다음 중 데이터 분석에 기초한 가치 창출과 관련된 설명으로 가장 부적절한 것은?', '핵심적인 비즈니스 이슈에 답을 주는 분석은 기업의 경쟁전략과 밀접하게 연관된다.', '복잡하고 다양한 데이터를 최적화 하는 능력이 최고의 가치를 창출하는 가장 중요한 기준이다.', '전략적 분석과 통찰력의 창출은 빅데이터 프로젝트에서 핵심적인 역할을 한다.', '기존 성과를 유지하고 업계를 따라잡는 것이 전략적 가치 기반 분석의 가장 중요한 목표는 아니다.', 2, '복잡한 데이터의 최적화 능력이 반드시 최고의 가치를 창출하는 것은 아니다. 전략적 통찰 없는 복잡한 분석은 쓸모없는 비즈니스 모델을 뒷받침하는 데 그칠 수 있다.', 100004, 'cbt'),
    (5, 1, '분석 적용대상', '다음 중 비즈니스에 분석을 적용할 때 효과적인 분석 적용 대상에 대한 검토와 관련된 설명으로 가장 부적절한 것은?', '사업적 잠재력만이 아니라 데이터 및 필요한 자원이 이용 가능한지를 고려해 대상을 택한다.', '조직이 분석을 배우는 동안에는 분석의 노력을 가능한 다양한 대상에 기울이도록 한다.', '업계 상황에 한정해서 바라보지 말고 더 넓은 시야에서 차별화를 고려한다.', '무엇이 가능한지 발견하기 위한 실험을 망설이지 말고 분석기회에 대한 직관을 무시하지 않는다.', 2, '조직이 분석을 도입하는 시기에는 노력을 너무 많은 대상에 기울이지 말고, 한 가지 주요 대상이나 몇 가지 작은 대상에 몰두하는 것이 바람직하다.', 100005, 'cbt'),
    (6, 1, '데이터 사이언티스트', '데이터 사이언티스트가 효과적인 분석 모델 개발을 위해 고려해야 하는 사항으로 가장 부적절한 것은?', '분석모델이 예측할 수 없는 위험을 살피기 위해 현실세계를 돌아보고 경험과 통찰력을 함께 활용한다.', '가정들과 현실의 불일치에 대해 끊임없이 고찰하고 모델의 능력에 대해 항상 의구심을 가진다.', '분석의 객관성에 의문을 제기하고 모델에 포함된 가정과 해석의 개입 등의 한계를 고려한다.', '넓은 시각에서 모델 범위 바깥의 요인들을 판단할 수 있도록 가능한 한 많은 상황 데이터를 모델에 포함한다.', 4, '모델 범위 밖의 요인을 판단하려는 것은 부적절하며 큰 위험을 동반할 수 있다. 지나치게 많은 과거 데이터를 모델에 포함하는 것도 모델의 정확성을 떨어뜨릴 수 있다.', 100006, 'cbt'),
    (7, 1, '의사결정 오류', '분석의 전형적인 의사결정 오류를 로직 오류와 프로세스 오류로 나눠 보았을 때, 각 오류에 대한 설명으로 가장 부적절한 것은?', '부정확한 가정을 하고 테스트를 하지 않는 것은 로직 오류이다.', '결정에서 분석과 통찰력을 고려하지 않는 것은 프로세스 오류이다.', '데이터 수집이나 분석이 너무 늦어 사용할 수 없게 되는 것은 로직 오류이다.', '대안을 진지하게 고려하지 않는 것은 프로세스 오류이다.', 3, '데이터 수집이나 분석이 너무 늦어 사용할 수 없게 되는 것은 프로세스 오류에 대한 설명이다.', 100007, 'cbt'),
    (8, 1, 'DIKW', '아래 내용은 데이터, 정보, 지식의 차이점을 예시로 설명한 것이다. 각각의 용어와 예시가 적절하게 연결된 것은? (가) A마트는 100원, B마트는 200원에 연필을 판매한다. (나) A마트의 연필가격이 더 싸다. (다) 상대적으로 저렴한 A마트에서 연필을 사야겠다. (라) A마트의 다른 상품도 B마트보다 저렴할 것이다.', '데이터-(가), 정보-(나), 지식-(다)', '데이터-(가), 정보-(나), 지식-(라)', '데이터-(가), 정보-(다), 지식-(라)', '데이터-(가), 정보-(라), 지식-(다)', 1, '(가)데이터: 가공 전 순수 사실, (나)정보: 데이터를 가공해 의미를 부여, (다)지식: 정보 패턴을 이해해 예측한 결과물, (라)지혜: 근본 원리에 대한 깊은 이해로 도출한 창의적 아이디어.', 100008, 'cbt'),
    (9, 1, '기업DB솔루션', '다음 중 기업내부 데이터베이스의 활용과 가장 관련이 없는 것은?', 'CRM(Customer Relationship Management)', 'ERP(Enterprise Resource Planning)', 'ITS(Intelligent Transport Systems)', 'KMS(Knowlege Management Systems)', 3, 'ITS(지능형교통체계)는 국가 교통 DB를 통해 교통소통을 목적으로 하는 사회기반 시스템으로, 기업내부 데이터베이스 활용과는 관련이 적다.', 100009, 'cbt'),
    (10, 1, '빅데이터 변화', '다음 중 빅데이터가 만들어 내는 변화와 가장 거리가 먼 것은?', '가치가 있을 것이라 예상되는 특정 정보만 모으는 것이 아니라 최대한 많은 데이터를 모아 숨은 정보를 찾아내는 방식이 중요해진다.', '데이터의 규모가 증가함에 따라 사소한 오류 데이터는 분석결과에 영향을 미치지 않기 때문에 포함해도 상관없는 경우가 많아진다.', '인과관계 규명 없이 상관관계 분석결과만으로도 인사이트를 얻고 수익을 창출할 기회가 늘어나고 있다.', '데이터의 양이 증가하고 유형이 복잡해짐에 따라 분석에 필요한 데이터를 선정하기 위한 정교한 표본조사 기법의 중요성이 대두되고 있다.', 4, '빅데이터 시대에는 정교한 표본조사보다 전수조사가 보편화되는 방향으로 변화한다.', 100010, 'cbt'),
    (11, 1, '빅데이터 기능', 'IoT시대가 되면 수많은 물건에 센서가 부착되어 데이터가 끊임없이 생산되는데, 빅데이터 사업자들이 이 데이터를 저장해 두고 3rd party에 API를 통해 공개하여 활용하도록 하는 빅데이터의 기능은?', '렌즈', '플랫폼', '원유', '산업혁명의 석탄', 2, "플랫폼은 '공동 활용의 목적으로 구축된 유·무형의 구조물'을 의미하며, API를 통한 데이터 공개·활용이 대표적 사례이다.", 100011, 'cbt'),
    (12, 1, '데이터 단위', '아래 제시된 데이터양의 표시 단위를 작은 것부터 큰 것의 순서로 나열하면? 가. 엑사바이트(EB) 나. 페타바이트(PB) 다. 요타바이트(YB) 라. 제타바이트(ZB)', '나-가-라-다', '가-나-다-라', '나-가-다-라', '다-라-가-나', 1, '테라(10^12)<페타(10^15)<엑사(10^18)<제타(10^21)<요타(10^24) 순이므로 나(PB)-가(EB)-라(ZB)-다(YB) 순이다.', 100012, 'cbt'),
    (13, 1, '빅데이터 경영혁신', '아래는 빅데이터로 달성할 수 있는 경영혁신의 단계를 나열한 것이다. 시작 단계에서 궁극적인 단계까지 바르게 나열된 것은? (가) 생산성 향상 (나) 발견에 의한 문제해결 (다) 의사결정 향상 (라) 새로운 고객가치와 비즈니스 창출', '(가) -> (나) -> (다) -> (라)', '(나) -> (다) -> (라) -> (가)', '(다) -> (라) -> (가) -> (나)', '(라) -> (가) -> (나) -> (다)', 1, '빅데이터 경영혁신은 생산성 향상 → 발견에 의한 문제해결 → 의사결정의 과학화·자동화(향상) → 새로운 고객가치와 비즈니스 창출 순으로 진행된다.', 100013, 'cbt'),
    (14, 1, '프라이버시 보호', "다음 중 연방거래위원회(FTC)가 제시한 '소비자 프라이버시 보호 3대 권고사항'에 해당되지 않는 것은?", '상품 개발 단계에서부터 소비자 프라이버시 보호 방안을 적용', '소비자 행동 예측 알고리즘에 대한 이해당사자의 접근권 보장', '소비자에게 수집된 정보 내용 공개 및 접근권 부여', '소비자에게 공유 정보 선택 옵션 제공', 2, '알고리즘 접근권 보장은 데이터 오용 위기요소에 대한 대응책이며, FTC의 프라이버시 3대 권고사항에는 해당하지 않는다.', 100014, 'cbt'),
    (15, 1, '소프트 스킬', '데이터 사이언티스트에게 필요한 하드 스킬과 소프트 스킬 중, 다음 중 소프트 스킬에 가장 가까운 것은?', 'Machine Learning', 'Statistics Modeling', 'Data Visualization', 'Distributed Computing', 3, '소프트 스킬에는 창의적 사고, 호기심, 논리적 비판, 스토리텔링, 시각화(Visualization), 커뮤니케이션 등이 있다.', 100015, 'cbt'),
    (16, 1, '데이터 기초', '다음 중 데이터에 대한 설명으로 가장 부적절한 것은?', '1바이트는 0에서 255까지의 정수 값을 표현할 수 있는 데이터의 크기를 의미한다.', '영어 한 글자는 1바이트로 저장할 수 있지만 한글 한 글자는 2바이트로 저장하는 것이 일반적이다.', '수치 데이터는 용량이 증가하더라도 텍스트 데이터에 비해 DBMS에서 관리하기 용이하다.', '설문조사 데이터는 그 형태와 형식이 정해져 있지 않아 비정형 데이터라고 한다.', 4, '설문조사의 주관식 응답은 비정형 데이터이지만, 객관식 응답은 수치로 처리 가능한 정형 데이터로 볼 수 있어 일괄적으로 비정형이라 할 수 없다.', 100016, 'cbt'),
    (17, 1, 'DW 특성', '데이터웨어하우스는 기업 내 의사결정지원 애플리케이션에 정보 기반을 제공하는 통합 저장 공간이다. 다음 중 데이터웨어하우스의 고유한 특성이 아닌 것은?', '데이터웨어하우스에서는 데이터의 지속적 갱신에 따른 데이터의 무결성 유지가 무엇보다 중요하다.', '데이터웨어하우스 데이터들은 전사적 차원에서 일관된 형식으로 정의된다.', '데이터웨어하우스에서 관리되는 데이터들은 시간의 흐름에 따라 변화하는 값을 저장한다.', '데이터웨어하우스에서는 특정 주제에 따라 데이터들이 분류, 저장, 관리된다.', 1, '데이터웨어하우스의 4대 특성은 주제 지향성, 데이터 통합, 시계열성(시간 가변성), 비휘발성이며, 지속 갱신에 따른 무결성 유지는 DW 고유의 특성이 아니다.', 100017, 'cbt'),
    (18, 1, '빅데이터 변화방향', '다음 중 빅데이터로 인한 변화방향을 기술한 것으로 가장 부적절한 것은?', '필요한 정보만을 수집하던 시대에서 가능한 많은 정보를 수집한 후 용도를 찾아내는 시대로의 변화', '단순한 상관관계보다 이론적 인과관계를 중시하는 방향으로 변화', '표본조사 보다 전수조사가 보편화되는 시대로의 변화', '데이터의 질보다 양을 중시하는 시대로의 변화', 2, '빅데이터 시대에는 이론적 인과관계보다 단순한 상관관계 분석 결과를 활용하는 것이 사업 목적상 더 부합하는 경우가 빈번해지고 있다.', 100018, 'cbt'),
    (19, 1, '빅데이터 출현배경', '다음 중 빅데이터의 출현 배경과 가장 거리가 먼 것은?', '하둡과 같은 분산처리 기술의 발전', 'M2M, IoT과 같은 통신 기술의 발전', '의료정보 등 공공데이터의 개방 가속화', '트위터, 페이스북 등 SNS의 급격한 확산', 3, '공공데이터의 개방은 빅데이터의 출현배경이라기보다는 빅데이터 현상 이후 이를 활성화하기 위한 후속 조치의 성격이 강하다.', 100019, 'cbt'),
    (20, 1, '5V 특징', '구글 번역 서비스에서 활용된 빅데이터의 특성으로 가장 적절한 것은? (수집한 문서가 많을수록 번역의 질이 높아진다는 가정에서 출발)', 'Volume', 'Variety', 'Velocity', 'Veracity', 1, '구글 번역은 전 세계에서 수집한 수십억 개의 문서를 기반으로 하며, 문서가 많을수록 번역 질이 높아진다는 점에서 Volume(규모) 특성을 활용한 사례이다.', 100020, 'cbt'),
    (21, 1, '빅데이터 위기요인', "빅데이터 시대의 부정적 측면 중 '책임원칙의 훼손' 이슈에 대한 사례로 가장 적절한 것은?", '범죄 예측 프로그램에 의해 범행 전에 체포', '빅브라더가 개인의 일상생활 전반을 감시', '여행 사실을 트윗한 사람의 집에 강도가 침입', '검색엔진의 검색결과의 차별적 누락에 따른 피해 발생', 1, '책임원칙 훼손은 예측 결과만으로 개인을 단죄하는 문제이며, 범행 전 체포가 대표 사례이다. 나머지는 사생활 침해·데이터 오용 사례이다.', 100021, 'cbt'),
    (22, 1, '빅데이터 개념', '다음 중 빅데이터에 관한 설명으로 가장 적절한 것은?', '빅데이터 분석을 통한 가치창출 여부는 데이터의 규모에 의해 크게 좌우된다.', '비즈니스 핵심에 대해 보다 객관적이고 종합적인 통찰을 줄 수 있는 데이터를 확보해야 한다.', '빅데이터 프로젝트를 추진하는데 있어 가장 큰 걸림돌은 막대한 소요비용이다.', '성과가 높은 기업의 대부분은 폭넓은 가치 분석적 통찰력을 갖추고 있는 것으로 밝혀졌다.', 2, '가치창출은 데이터 규모보다 객관적·종합적 통찰을 줄 수 있는 데이터 확보가 중요하며, 걸림돌은 비용이 아니라 분석적 방법과 성과에 대한 이해 부족이다.', 100022, 'cbt'),
    (23, 1, '시대별 용어', 'OLAP - 다차원의 데이터를 대화식으로 분석하기 위한 소프트웨어, ( ㉠ ) - 데이터 기반 의사결정을 지원하기 위한 리포트 중심의 도구, Analytics - 통계적·수학적 분석에 초점을 둔 기법. ㉠에 들어갈 용어는?', 'Business Intelligence(BI)', 'Business Analytics(BA)', 'Data Mining', 'OLTP', 1, 'BI(Business Intelligence)는 데이터 기반 의사결정을 지원하기 위한 리포트 중심의 도구이다.', 100023, 'cbt'),
    (24, 1, '데이터 사이언스', '컴퓨터공학, 통계학, 수학 등의 학문적 지식과 시각화 및 해커로서의 소양까지 종합한 학문으로, 기존 통계학과 다르게 총체적 접근법을 사용하는 이것은 무엇인가?', '데이터 사이언스', '데이터 마이닝', '빅데이터 거버넌스', '비즈니스 애널리틱스', 1, '데이터 사이언스는 여러 학문 지식을 종합하며, 기존 통계학과 달리 총체적(holistic) 접근법을 사용한다.', 100024, 'cbt'),
    (25, 1, '정량적 데이터', '다음 중 정량적 데이터(Quantitative data)의 예로서 부적절한 것은?', '직업', '강우량', '영업이익', 'GDP 증가율', 1, '직업은 수치·기호·도형으로 표시하기 어려운 정성적 데이터이다.', 100025, 'cbt'),
    (26, 1, '암묵지 예시', '다음 중 암묵지(Tacit knowledge)의 예로서 부적절한 것은?', '고려청자를 만드는 비법', '간장의 맛을 결정한다는 시어머니의 손맛', '연봉이 수억에 달한다는 보험설계사의 영업비밀', '회계규칙에 입각하여 대차대조표를 작성하는데 요구되는 지식', 4, '회계규칙에 따른 대차대조표 작성 지식은 문서화·정리된 형식지에 해당한다.', 100026, 'cbt'),
    (27, 1, '빅데이터 활용기법', '최대의 시청률을 얻으려면 어떤 프로그램을 어떤 시간대에 방송해야 하는가라는 문제 해결에 가장 적절한 분석방법은?', '소셜 네트워크 분석(Social network analysis)', '유전 알고리즘(Genetic algorithm)', '기계 학습(Machine learning)', '유형 분석(Classification tree analysis)', 2, '유전 알고리즘은 자연선택·돌연변이 메커니즘으로 점진적으로 진화시켜 최적화 문제의 해결책을 찾는 기법이다.', 100027, 'cbt'),
    (28, 1, '비정형데이터', '다음 중 비정형데이터로 분류하기에 가장 부적절한 것은?', 'IE 웹브라우저로 Gmarket에 접속한 로그기록', 'Naver의 검색창에 입력한 키워드', 'Facebook 친구에게 게시한 댓글', 'Galaxy S5로 찍은 셀카 사진', 1, '웹 접속 로그기록은 형태가 있고 일정한 형식(키-값 등)을 가지는 반정형 데이터로 보는 것이 적절하다.', 100028, 'cbt'),
    (29, 1, '가치 패러다임', '빅데이터 시대에 가치 패러다임이 변화하는 단계를 올바르게 나열한 것은?', '연결(Connection) -> 디지털화(Digitalization) -> 에이전시(Agency)', '디지털화(Digitalization) -> 연결(Connection) -> 에이전시(Agency)', '에이전시(Agency) -> 연결(Connection) -> 디지털화(Digitalization)', '연결(Connection) -> 에이전시(Agency) -> 디지털화(Digitalization)', 2, '가치 패러다임은 디지털화 → 연결 → 에이전시의 3단계로 변화한다.', 100029, 'cbt'),
    (30, 1, '데이터베이스 특징', '다음 중 데이터베이스의 특징에 대한 설명으로 가장 부적절한 것은?', '데이터베이스는 통합된 데이터(Integrated data)이다.', '데이터베이스는 다양한 방법으로 필요한 정보를 검색할 수 있는 검색가능성을 가진다.', '데이터베이스는 여러 사용자가 서로 단일한 목적으로 데이터를 공동으로 이용할 수 있도록 구성되어야 한다.', '데이터베이스는 변화되는 데이터로 삽입, 삭제, 갱신에도 항상 현재의 정확한 데이터를 유지해야 한다.', 3, "데이터베이스는 여러 사용자가 서로 '다른' 목적으로 데이터를 공동 이용하는 공용 데이터(Shared Data)를 특징으로 한다.", 100030, 'cbt'),
    (31, 1, 'SQL', "SELECT CUSTOMER_NAME 고객명, E_CUSTOMER_NAME 고객영문명 FROM CUSTOMER WHERE E_CUSTOMER_NAME LIKE '_A%'; 를 실행했을 때 출력되는 결과로 옳은 것은?", '영문명이 A로 시작하는 고객들의 이름', '영문명이 두 번째 문자가 A인 고객들의 이름', '영문명이 A나 a로 시작하는 고객들의 이름', '위치에 상관없이 영문명에 A를 포함하는 고객들의 이름', 2, "'_'는 문자 하나를 대표하는 와일드카드이므로 '_A%'는 두 번째 문자가 A인 문자열과 일치한다.", 100031, 'cbt'),
    (32, 1, 'SQL', '아래 SQL 명령 중 DML(Data Manipulation Language)에 해당하는 항목을 모두 나열한 것은? (A) DELETE (B) INSERT (C) SELECT (D) UPDATE (E) CREATE', '(A), (B)', '(A), (B), (C)', '(A), (B), (C), (D)', '(A), (B), (C), (D), (E)', 3, 'DELETE, INSERT, SELECT, UPDATE는 DML이며, CREATE는 DDL(데이터 정의어)에 해당한다.', 100032, 'cbt'),
    (33, 1, '빅데이터 파급효과', '빅데이터가 기업에 주는 영향으로 혁신 촉진, 경쟁력 제고, 그리고 ( ㉠ ) 향상을 들 수 있다. ㉠은?', '생산성', '안정성', '보안성', '수익성', 1, '빅데이터 활용으로 기업 운용 효율성이 증가하면 산업 전체의 생산성이 향상된다.', 100033, 'cbt'),
    (34, 1, '스키마', '( ㉠ )은(는) 데이터베이스의 구조와 제약조건에 관한 전반적인 명세를 의미하며, 개체·속성·관계 및 데이터 조작 시 제약 조건을 정의한다. ㉠은?', '스키마(Schema)', '메타데이터', '인덱스', '트랜잭션', 1, '스키마는 데이터베이스의 구조·자료 표현 방법·자료 간 관계를 형식 언어로 정의한 구조이다.', 100034, 'cbt'),
    (35, 1, '빅데이터 정의', '다음 중 일반적으로 통용되고 있는 빅데이터의 정의와 가장 거리가 먼 것은?', '일반적인 데이터베이스 소프트웨어로 저장·관리·분석할 수 있는 범위를 초과하는 규모의 데이터이다.', '다양한 종류의 대규모 데이터로부터 저렴한 비용으로 가치를 추출하는 차세대 기술 및 아키텍처다.', '데이터의 양, 다양성, 속도가 급격히 증가하면서 나타난 현상이다.', '기존 작은 데이터 처리로는 얻을 수 없었던 통찰과 가치를 하둡(Hadoop)을 기반으로 하는 대용량 분산처리 기술을 통해서만 창출하는 방식이다.', 4, '하둡은 대량의 자료를 처리하는 분산 응용 프로그램 지원 프레임워크일 뿐, 빅데이터 창출이 하둡 기술로만 이루어지는 것은 아니다.', 100035, 'cbt'),
    (36, 1, '빅데이터 기능', '다음 중 구글의 Ngram Viewer는 빅데이터의 어떤 기능을 보여주는 사례라고 할 수 있는가?', '현미경', '21세기의 오일(oil)', '차세대 산업혁명의 에너지원', '플랫폼', 1, 'Ngram Viewer는 특정 말뭉치의 시대별 사용 빈도를 비교해 보여주는 서비스로, 현미경처럼 특정 시점을 확대해 보여주는 기능에 비유된다.', 100036, 'cbt'),
    (37, 1, '빅데이터 위기요인', '다음 중 빅데이터의 위기요인 통제를 위해 논의되고 있는 방안에 대한 설명으로 가장 부적절한 것은?', '개인정보 활용에 대한 동의제를 책임제로 전환하는 것은 책임원칙 훼손 위기에 대한 통제방안으로 효과적이다.', '개인정보의 가치 증가와 기술발전으로 사생활침해 가능성도 커져 가이드라인 제정 요구가 급증하고 있다.', '데이터 오용의 위기 요소 대응책으로 알고리즘 접근권 보장과 알고리즈미스트의 필요성이 대두되고 있다.', '특정인이 채용·대출·신용카드 발급 결정 등에서 예측 자료로 불이익을 당할 가능성을 최소화하는 장치가 필요하다.', 1, "동의제에서 책임제로의 전환은 '사생활 침해' 위기에 대한 통제 방안이며, 책임원칙 훼손에 대해서는 기존 책임원칙 자체를 보강·강화하는 것이 논의된다.", 100037, 'cbt'),
    (38, 1, 'CRM', '빅데이터 시대가 도래함에 따라 CRM 환경이 바뀌고 있다. 다음 중 이와 관련된 설명으로 옳지 않은 것은?', '다양한 채널로 CRM 수행이 가능하게 되었다.', 'CRM의 목적과 방법이 변화하고 있다.', '기업과 고객 간 양방향 소통이 가능한 서비스 플랫폼이 활성화되고 있다.', '실시간으로 고객 트렌드를 파악할 수 있게 되었다.', 2, '오늘날 CRM은 기존 목적은 유지하면서 방법론(채널·기술)에서 다양한 변화를 모색하고 있다.', 100038, 'cbt'),
    (39, 1, '데이터vs정보', '데이터(data)와 정보(information)의 차이를 구분할 때, 다음 중 정보에 대한 예로 가장 부적절한 것은?', '평균 구매액', '주문수량', '베스트셀러', '우량고객', 2, '주문수량은 가공되지 않은 사실 그 자체인 데이터에 해당하며, 나머지는 데이터를 가공해 의미를 부여한 정보의 예시이다.', 100039, 'cbt'),
    (40, 1, '분석테크닉', '다음 중 데이터 분석 테크닉에 대한 설명 중 가장 부적절한 것은?', '개인의 신용 평가에 가장 많이 활용되는 것은 연관 규칙 학습이다.', '기계 학습은 대규모 데이터를 처리·분석할 때 상당한 분석 인프라와 시간이 소요될 수 있다.', '한국어의 경우 언어적 특성으로 인해 감정 분석에 상대적으로 어려운 측면이 있다.', '소셜 네트워크 분석은 최근 핀테크 기업에서 대출을 제공할 때 활용되고 있다.', 1, '개인 신용 평가에 가장 많이 활용되는 기법은 회귀 분석이다.', 100040, 'cbt'),
    (41, 1, '데이터 사이언티스트', '다음 중 뛰어난 데이터 사이언티스트에 대한 설명으로 가장 적절한 것은?', '통계학에 대한 이론적 지식과 최적의 분석 설계 노하우를 축적하는 것이 가장 중요하다.', '정량 분석이라는 과학과 인문학적 통찰에 근거한 합리적인 추론을 조합한다.', '분석 결과를 인간의 해석이 개입하지 않도록 객관적으로만 사용한다.', '분석에 현실이 개입하지 않도록 최대한 긍정적인 가정과 모델들에 기초한다.', 2, '뛰어난 데이터 사이언티스트는 정량 분석이라는 과학과 인문학적 통찰에 근거한 합리적 추론을 탁월하게 조합한다.', 100041, 'cbt'),
    (42, 1, 'DBMS', '사용자와 데이터베이스 사이에서 사용자의 요구에 따라 정보를 처리해주고 데이터베이스를 관리해주는 소프트웨어는?', 'DBMS', 'Data Dictionary', 'SQL', 'ERD', 1, 'DBMS(DataBase Management System)는 사용자의 요구에 따라 정보를 처리하고 데이터베이스를 관리하는 소프트웨어이다.', 100042, 'cbt'),
    (43, 1, '비식별화', '데이터에 포함된 개인 식별 정보를 삭제하거나 알아볼 수 없는 형태로 변환하는 것으로, 가명·일반화·치환·섭동 등의 방법으로 구현하는 이것은?', '데이터 익명화(Data Anonymity)', '데이터 마스킹', '데이터 암호화', '접근 통제', 1, '데이터 익명화는 개인 식별 정보를 삭제하거나 알아볼 수 없게 변환하는 것으로, 가명·일반화·치환·섭동 등 다양한 방법을 포함한다.', 100043, 'cbt'),
    (44, 1, 'DW 특성', '다음 중 데이터웨어하우스에 대한 설명으로 가장 부적절한 것은?', '기업 내 의사결정지원 애플리케이션을 위한 정보 기반을 제공하는 통합된 데이터 저장 공간이다.', 'ETL은 내부·외부 데이터베이스로부터 정보를 추출·변환한 후 데이터웨어하우스에 적재한다.', '데이터웨어하우스에서 관리하는 데이터들은 시간의 흐름에 따라 변화하는 값을 유지한다.', '일반적으로 전사적 차원에서 접근하기보다는 재무·생산 등 특정 업무 분야에 맞춰 초점을 맞추어 구축된다.', 4, '전사적 차원보다 특정 업무 분야에 초점을 맞춰 구축되는 것은 데이터 마트의 특징이며, 데이터웨어하우스는 전사적 차원에서 구축된다.', 100044, 'cbt'),
    (45, 1, '기업 정보시스템', '기업 전체를 경영자원의 효과적 이용이라는 관점에서 통합적으로 관리하고 경영의 효율화를 기하기 위한 시스템은?', 'ERP', 'CRM', 'SCM', 'KMS', 1, 'ERP(전사적자원관리)는 기업 활동 전반의 경영자원을 통합 관리하여 경영 효율화를 기하는 시스템이다.', 100045, 'cbt'),
    (46, 1, '인문학적 사고', '최근 인문학적 사고의 필요성이 대두하게 된 사회경제적 환경의 변화를 기술한 것 중 가장 관련이 없는 것은?', '단순한 세계화에서 복잡한 세계화로 변화하고 있다.', '비즈니스의 중심이 제품생산에서 서비스로 이동하고 있다.', '경제와 산업의 논리가 생산에서 시장창조로 바뀌고 있다.', '직관 보다는 데이터에 기반한 의사결정이 더욱 중요해지고 있다.', 4, '데이터 기반 의사결정이 중요해지는 것은 인문학적 사고 대두의 배경과는 직접적인 관련이 없다.', 100046, 'cbt'),
    (47, 1, 'DIKW', 'DIKW 피라미드에서 상호 연결된 정보 패턴을 이해하여 이를 토대로 예측한 결과물을 무엇이라고 하는가?', '지식(Knowledge)', '정보(Information)', '지혜(Wisdom)', '데이터(Data)', 1, '지식은 상호 연결된 정보 패턴을 이해하여 이를 토대로 예측한 결과물이다.', 100047, 'cbt'),
    (48, 1, '데이터 무결성', '데이터 ( ㉠ )은(는) 데이터베이스 내 데이터의 정확성, 일관성, 유효성, 신뢰성을 보장하기 위해 데이터 변경·수정 시 여러 제한을 두어 정확성을 보증하는 것을 말한다. ㉠은?', '무결성(Integrity)', '일관성(Consistency)', '가용성(Availability)', '기밀성(Confidentiality)', 1, '데이터 무결성은 데이터의 정확성·일관성·유효성·신뢰성을 보장하기 위한 제약과 통제를 의미한다.', 100048, 'cbt'),
    (49, 2, '정보보안 거버넌스', '다음 중 정보보안 거버넌스에 대한 설명으로 가장 부적절한 것은?', '정보보안 거버넌스는 기업의 정보보안 전략을 정보보안 자원에 전략적으로 연계하는 것을 목적으로 한다.', '정보보안 거버넌스는 IT 거버넌스와는 독립적인 영역이다.', '정보보안 거버넌스는 정보를 보호하는 리더십, 조직구조, 프로세스로 구성되어 있다.', '정보보안 거버넌스의 3요소는 데이터 무결성, 서비스 연속성, 정보자산 보호이다.', 2, '정보보안 거버넌스는 IT 거버넌스의 구성요소를 그대로 따르며, IT 거버넌스에 포함되는 영역으로 볼 수 있다(독립적인 영역이 아님).', 100049, 'cbt'),
    (50, 2, '분석체계 구현', '비즈니스 영역별로 도출된 분석과제를 대상으로 조직에 적합한 분석체계를 구현할 때, 다음 중 설명으로 가장 부적절한 것은?', '분석체계 구현은 설계 -> 구현 -> 테스트 -> 이행 등 순차적(Waterfall) 방식을 적용하여 수행한다.', '분석을 위해 필요한 데이터를 수집 및 확보한 후 분석 모델을 설계한다.', '준비된 데이터를 분석 모델에 적용하고 그 결과를 평가한다.', '분석모델을 반복적으로 정련하여 분석 모델을 최적화 한다.', 1, '분석체계 구현은 순차적(Waterfall) 방식이 아니라, 데이터 수집·모델 설계·적용·평가를 반복하며 모델을 최적화하는 반복적 정련 방식으로 이루어진다.', 100050, 'cbt'),
    (51, 2, '프로세스 혁신', '빅데이터 시대에 기업들이 고민해야 하는 프로세스 혁신의 방향에 대한 설명으로 가장 부적절한 것은?', '이슈 중심의 상향식(Bottom Up)이 아닌 비즈니스 모델 및 시나리오 기반의 하향식(Top-Down) 접근', '업무 처리의 신속성과 시장대응 민첩성을 중심으로 프로세스의 중복제거·단순화·표준화 관점에서 진행', 'Time-to-Market(신속성) 관점이 아닌 Quality-to-Market(최적화) 관점의 업무처리 지능화를 통한 효과성 향상에 포커싱', '업무프로세스 실행시점에 필요한 Action을 강제화 할 수 있도록 Analytics의 프로세스 내재화 관점의 접근', 2, "빅데이터 시대의 프로세스 혁신은 '신속성·민첩성 중심의 중복제거·단순화·표준화'가 아니라, 업무 효과성·기획평가 중심으로 방향이 바뀌어야 한다.", 100051, 'cbt'),
    (52, 2, '의사결정 최적화', '의사결정 최적화의 장애요인이 아닌 것은?', '데이터 지연(Data Latency)', '분석 지연(Analytic Latency)', '모델 검증 지연(Verification Latency)', '의사결정 지연(Decision Latency)', 3, '의사결정 최적화를 방해하는 3가지 지연 요인은 데이터 지연, 분석 지연, 의사결정 지연이다.', 100052, 'cbt'),
    (53, 2, '분석 선순환 구조맵', '특정 부서 분석 결과가 다른 조직에 미치는 영향을 전사 목표 최적화 관점에서 파악하기 위해, 분석 목록을 선택과 결과로 모델링하여 결과요소 간 상충 여부 등을 확인하는 도구로 가장 적절한 것은?', '분석 선순환 구조 맵', '액티비티 맵', '전략캔버스', '유저스토리', 1, '분석 선순환 구조 맵은 분석 목록을 선택과 결과로 모델링해 연관성과 상충 요소를 확인하는 도구이다.', 100053, 'cbt'),
    (54, 2, '지연시간', '의사결정 및 업무 운영 최적화를 위해 줄여야 하는 3가지 지연 시간은 ( ㉠ ) 지연 시간, 분석 지연 시간, 의사결정 지연 시간이다. ㉠은?', '데이터', '시스템', '네트워크', '검증', 1, '3가지 지연시간은 데이터 지연, 분석 지연, 의사결정 지연 시간이다.', 100054, 'cbt'),
    (55, 2, '잊힐 권리', '온라인·SNS 상 개인의 사진·거래·성향 정보에 대해 소유권을 강화하고 삭제·수정·영구 파기를 요청할 수 있는 권리 개념은?', '잊힐 권리(Right to be forgotten)', '정보 접근권', '알 권리', '자기결정권', 1, "잊힐 권리는 디지털 환경에서 '지워지지 않는 기록' 문제를 다루는 개념으로, 옥스퍼드대 빅토어 마이어 쇤베르거가 처음 언급하였다.", 100055, 'cbt'),
    (56, 2, '우선순위 평가', '다음 중 데이터 분석 구현을 위한 적용 우선순위 평가 시 주요 고려요소가 아닌 것은?', '전략적 중요도', '분석 데이터 적용 수준', '분석 ROI', '실행 용이성', 2, '우선순위 평가 요소는 전략적 중요도, 분석 ROI, 실행 용이성이며, 분석 데이터 적용 수준은 적용 범위·방식에 대한 고려요소이다.', 100056, 'cbt'),
    (57, 2, '분석조직구조', '데이터 분석을 위한 조직구조 중 집중형 분석 조직구조의 특징으로 가장 부적절한 것은?', '전사 분석 업무를 별도 독립된 분석 전담조직에서 담당한다.', '분석 결과에 대한 신속한 실행(Action)이 가능하다.', '전략적 중요도에 따라 분석 조직이 우선순위를 정하여 추진 가능하다.', '현업 업무부서의 분석업무와 이중화 또는 이원화 될 가능성이 높다.', 2, '분석 결과의 신속한 실행(Action)이 가능한 것은 분산형 조직구조의 특징이며, 집중형은 현업부서와 이중화 가능성이 있다.', 100057, 'cbt'),
    (58, 2, '빅데이터 품질관리', '빅데이터와 정형 데이터를 품질관리 측면에서 비교할 때, 빅데이터 품질관리의 특성으로 볼 수 없는 것은?', '데이터에 대한 오너쉽이 더 강하다.', '이미 생성된 데이터에 대한 정제(정비)가 어렵다.', '개별 데이터에 대한 타당성 검증은 경우에 따라 불필요하다.', '혹시 발생할지 모르는 데이터 사용자의 오류는 무시할 수 있다.', 4, '데이터 사용자의 오류를 무시할 수 있다는 것은 빅데이터 품질관리의 특성이 아니다.', 100058, 'cbt'),
    (59, 2, '빅데이터 보안', '빅데이터 보안에 대한 접근 방법으로 가장 부적절한 것은?', '개인정보 외 외부에 공개가 어려운 민감성 데이터는 용도를 명확히 하고, 경우에 따라 사용이 불가하다.', '모든 데이터의 품질을 보장하기 위한 기준을 정의해야 한다.', 'DBMS에 저장할 필요가 없는 일회성 데이터에 대한 보안검사는 경우에 따라 불필요하다.', '기관 또는 기업 간 연계를 통해 공유·분산된 데이터에 대한 보안검사는 경우에 따라 불필요하다.', 2, '모든 데이터의 품질을 일률적으로 보장하기보다, 빅데이터의 특성을 고려해 보안·보호되어야 할 데이터와 수준의 기준을 정의해야 한다.', 100059, 'cbt'),
    (60, 2, '분석기회 발굴', '기업에 비즈니스 성과를 이끌어 줄 분석기회(Analytic Use Case)를 찾는 방법으로 가장 부적절한 것은?', '기업의 비즈니스 모델분석을 통해 경쟁력 강화를 위한 핵심 분석기회를 식별한다.', '특정 대상 프로세스를 선정한 후 업무 주제별로 분석 요건을 식별한다.', '제공되는 산업별, 업무 서비스 별 분석 테마 후보 풀의 벤치마킹을 통해 분석기회를 식별한다.', '기업에 축적되어 있는 모든 데이터들을 분석하여, 비즈니스적 인사이트를 찾기 위해 노력한다.', 4, '모든 데이터를 무작정 분석해 인사이트를 찾는 것은 비용 효율적이지 못하며, 분석 대상·목적을 명확히 정의하고 점진적으로 확대하는 것이 효율적이다.', 100060, 'cbt'),
    (61, 2, '고객가치유형', '고객의 니즈를 구성하는 4가지 가치 유형(Customer Value Wedge) 중 무형의 가치(Intangible Value)와 관련되지 않은 것은?', '공유성', '확장성', '접근성', '즐거움', 4, '즐거움은 감성 가치(Emotional Value)의 요소이며, 무형의 가치 요소가 아니다.', 100061, 'cbt'),
    (62, 2, '경영혁신 도구', '기업 전략을 비주얼한 차트 형태로 표현하고, 고객 효용 관점에서 자사·경쟁사의 가치수준을 비교해 새로운 전략방향을 설정하도록 돕는 경영혁신 도구는?', '전략 캔버스', 'ERRC 프레임워크', '비즈니스 컨텍스트', '구매자 효용 지도(Buyer Utility Map)', 1, '전략 캔버스는 블루오션 전략의 핵심 도구로, 고객 시각에서 자사와 경쟁사의 가치 수준을 비교·표현한다.', 100062, 'cbt'),
    (63, 2, 'CLD 선택유형', "선택(Choice)-이론(Theory)-결과(Consequence) 형태의 비즈니스 운영 시나리오에서 '선택'의 3가지 유형이 아닌 것은?", '정책(Policy)', '자산(Asset)', '거버넌스(Governance)', '전략(Strategy)', 4, '선택(Choice)의 3가지 유형은 정책, 자산, 거버넌스이며, 전략은 이에 해당하지 않는다.', 100063, 'cbt'),
    (64, 2, '분석 유즈케이스', '기업의 전사 또는 개별 업무별 주요 의사결정 포인트에 활용할 수 있는 분석의 후보로, 비즈니스 모델의 이론(Theory)을 설명하고 하나 이상의 분석을 포함하며 프로세스 혁신의 수단으로 사용되는 것은?', '분석기획(분석 유즈 케이스, Analytic Use Case)', '데이터 거버넌스', '비즈니스 모델 캔버스', '분석 마스터플랜', 1, '분석 유즈 케이스는 의사결정 포인트에 활용되는 분석 후보로, 비즈니스 모델의 이론을 설명하고 프로세스 혁신의 수단이 된다.', 100064, 'cbt'),
    (65, 2, '분석 성숙도 영역', "분석 성숙도(Maturity) 단계 진단 시 각 단계별 조직의 성숙도를 진단하는 3가지 영역은 '비즈니스 부문', 'IT 부문', '( ㉠ ) 부문'이다. ㉠은?", '조직·역량', '재무', '마케팅', '고객', 1, '분석 성숙도는 비즈니스, 조직·역량, IT 3가지 부문에서 진단한다.', 100065, 'cbt'),
    (66, 2, '빅데이터 투자요소', '다음 빅데이터의 특징 중 투자비용 요소 또는 난이도를 평가하는 요소로 가장 부적절한 것은?', '규모(Volume)', '다양성(Variety)', '속도(Velocity)', '가치(Value)', 4, 'Volume·Variety·Velocity(3V)는 투자비용·난이도 평가 요소이며, Value는 비즈니스 효과(시급성 평가) 요소이다.', 100066, 'cbt'),
    (67, 2, '분석 준비도', '기업의 데이터 분석 도입 수준을 파악하기 위한 분석 준비도(Readiness) 측정 요소로 가장 부적절한 것은?', '분석 목표 및 전략', '분석 업무', '분석 데이터', '분석 인력 및 조직', 1, "분석 준비도는 분석업무, 분석 인력 및 조직, 분석 기법, 분석 데이터, 분석 문화, 분석 인프라의 6개 영역으로 진단하며 '분석 목표 및 전략'은 해당하지 않는다.", 100067, 'cbt'),
    (68, 2, '데이터 품질관리', '데이터 품질관리에 대한 설명으로 가장 부적절한 것은?', '조직 내·외부의 정보시스템 및 DB 사용자의 기대를 만족시키기 위해 지속적으로 수행하는 관리·개선활동을 의미한다.', '품질관리 대상은 데이터 값, 데이터 구조, 데이터 관리 프로세스이다.', '기업 내부에서 발생되는 정형 데이터에 대한 품질만을 의미한다.', '데이터 표준화, 메타데이터 관리, MDM을 통해 사전·사후 품질 향상 효과를 얻을 수 있다.', 3, '데이터 품질관리는 정형 데이터뿐 아니라 비정형·반정형 데이터의 품질관리도 포함하는 개념이다.', 100068, 'cbt'),
    (69, 2, '빅데이터 이익실현 장애물', '빅데이터 프로젝트에서 이익 실현 역량을 방해하는 3가지 요소(ISACA)와 가장 거리가 먼 것은?', '전문 분석인력을 단기간에 확보하기 어려움(전문가 부족)', '조직 간 정보 공유에 소극적이며 정보 활용도가 낮음(사일로 조직)', '수집·생성된 데이터의 품질을 확보할 수 없음', 'IT부서를 거치지 않고 현업이 바로 추진해 대규모 숨은 데이터가 발생함(섀도우 IT)', 3, 'ISACA가 제시한 3대 장애물은 전문가 부족, 사일로 조직, 섀도우 IT의 부상이며, 일반적인 데이터 품질 확보 이슈는 이 3대 장애물에 포함되지 않는다.', 100069, 'cbt'),
    (70, 2, '분석 내재화', '분석(Analytics)의 업무 프로세스 내재화를 구현하기 전 고려해야 할 요소가 아닌 것은?', '내재화를 전체 업무 프로세스에 일괄 적용할 준비가 되어 있는가?', '분석 알고리즘(로직)을 어떻게 설계할 것인가.', '독립된 정보계와는 달리 업무운영 시스템에 내재될 수 있는 융합성을 가지는가.', '대용량 데이터에 대해 필요한 시점에 적합한 속도로 분석을 제공하는가.', 1, '내재화는 전체 프로세스에 일괄 적용하는 것이 아니라 특정 프로세스별로 점진적으로 적용하는 것이 바람직하다.', 100070, 'cbt'),
    (71, 2, '구현 로드맵', '마스터플랜 수립 단계에서 분석과제를 도출한 후 데이터 분석구현을 위한 로드맵 수립 시 고려되는 요소 중 성격이 다른 하나는?', '기술 적용 수준', '분석 데이터 적용 수준', '전략적 중요도 수준', '업무 내재화 적용 수준', 3, "기술·데이터·업무내재화 적용 수준은 '적용 범위/방식' 요소이고, 전략적 중요도는 '우선순위'를 결정하는 요소로 성격이 다르다.", 100071, 'cbt'),
    (72, 2, '비즈니스 모델', "'기업운영 방식의 표현', '조직이 가치를 만들고 제공하며 획득하는 근본 원리의 표현', '기업을 어떻게 경영하느냐를 설명하는 이야기' 라는 정의가 공통으로 설명하는 것은?", '비즈니스 모델(Business Model)', '비즈니스 전략(Strategy)', '비즈니스 컨텍스트', '분석 마스터플랜', 1, '비즈니스 모델은 기업운영 방식과 가치 창출·제공·획득의 근본 원리를 표현하는 개념이다. 전략은 경쟁사보다 무엇을 잘할지를 설명한다는 점에서 구별된다.', 100072, 'cbt'),
    (73, 2, '빅데이터 특징(4V)', '분석과제의 적용 우선순위를 선정하는 기준 중 빅데이터의 4V에서 난이도를 판단하는 요소로 부적절한 것은?', 'Volume(규모)', 'Variety(다양성)', 'Velocity(속도)', 'Value(가치)', 4, 'Volume·Variety·Velocity는 난이도(투자비용) 판단 요소이며, Value는 시급성(비즈니스 효과) 판단 요소이다.', 100073, 'cbt'),
    (74, 2, '분석 성숙도 단계', '전사 차원에서 분석을 관리·공유하고, 분석 전담 조직과 데이터 사이언티스트를 확보하며, 전사 성과의 실시간 분석과 분석 규칙·이벤트 관리가 가능한 성숙 단계는?', '도입단계', '활용단계', '확산단계', '최적화단계', 3, '확산단계는 전사 차원에서 분석을 관리·공유하고 전담 조직을 운영하며 실시간 분석이 가능한 단계이다.', 100074, 'cbt'),
    (75, 2, '분석조직구조', '별도의 독립된 분석 전담조직을 구성해 전사 차원의 분석업무를 수행하고 전략적 중요도에 따라 우선순위를 정해 추진이 가능하지만, 비즈니스 부서와 이중화 가능성이 있는 조직 형태는?', '분산형 조직구조', '가상형 조직구조', '집중형 조직구조', '기능형 조직구조', 3, '집중형 조직구조는 별도 전담조직(CoE)이 전사 분석업무를 담당하며 현업부서와 이중화될 가능성이 있다.', 100075, 'cbt'),
    (76, 2, '고객가치유형', '고객의 니즈를 구성하는 4가지 가치 유형(Customer Value Wedge)에 해당하지 않는 것은?', '기능적 가치(Functional Value)', '재무적 가치(Financial Value)', '감성 가치(Emotional Value)', '사회적 가치(Social Value)', 4, '4가지 가치 유형은 기능적 가치, 재무적 가치, 무형의 가치, 감성 가치이며 사회적 가치는 해당하지 않는다.', 100076, 'cbt'),
    (77, 2, 'BI 목적', '1990년대 이후 기업들이 Business Intelligence를 도입하며 기대했던 사항과 가장 거리가 먼 것은?', '과거 성과를 측정하고 비즈니스 계획에 참고할 수치를 사용할 수 있다.', '과거에 무슨 일이 발생했는지, 어디에·얼마나·얼마나 자주 문제가 있었는지 답을 얻을 수 있다.', '사용자는 모든 데이터에 접근해 EDW에 축적해 두면 유용한 정보를 산출할 것이다.', '왜 이런 일이 발생했는가, 다음에 무슨 일이 발생할 것인가, 최적의 선택은 무엇인가에 답을 제공해 준다.', 4, "'왜, 앞으로 어떻게, 최적의 선택은 무엇인가'에 답하는 것은 BI가 아닌 Business Analytics의 목표에 해당한다.", 100077, 'cbt'),
    (78, 2, '빅데이터 필요역량', '빅데이터의 3V(Volume, Variety, Velocity)를 고려할 때 성공적 안착을 위해 기업들이 반드시 갖추어야 할 역량으로 가장 부적절한 것은?', '빅데이터를 수용할 수 있는 스토리지와 빠른 추출 능력이 필요함', '데이터 기반의 의사결정 체계가 필요함', '빅데이터 분석을 위해 기업외부 비정형 데이터에만 집중해야 함', '실시간으로 발생되는 수많은 데이터에 대한 빠른 분석처리가 필요함', 3, '빅데이터는 외부 비정형 데이터뿐 아니라 내부 정형·반정형 데이터까지 종합적으로 다루어야 한다.', 100078, 'cbt'),
    (79, 2, '우선순위 결정요소', '분석과제의 우선순위를 결정하는 요소로서 가장 부적합한 것은?', '과제의 시급성과 난이도', '비즈니스 효과', '투자비용 요소', '전술적 중요도와 MBO', 4, "분석과제 우선순위는 시급성(비즈니스 효과)과 난이도(투자비용)로 결정하며, '전술적 중요도와 MBO'는 해당 기준이 아니다.", 100079, 'cbt'),
    (80, 2, '분석 도입 성공요소', '데이터 분석 도입의 성공요소로 가장 부적절한 것은?', '질문에 앞서 필요한 분석이 무엇인지 찾는다.', '핵심 분석을 발굴하고 이를 점진적으로 확장한다.', '분석 업무 의사결정 프로세스를 정립한다.', '의사결정을 위한 분석도구를 업무에 내재화해 강제적으로 실행하게 한다.', 1, '분석 도입은 필요한 분석을 먼저 찾기보다, 핵심 분석을 발굴해 점진적으로 확장하고 의사결정 프로세스를 정립하는 것이 성공요소로 강조된다.', 100080, 'cbt'),
    (81, 2, '상향식 접근절차', '비즈니스 모델 분석의 상향식(Bottom Up) 접근방식에서 특정 업무영역의 주제 지향적 분석기회를 발굴하는 절차로 올바르게 연결된 것은?', '프로세스 분류 → 분석요건 정의 → 분석요건 식별 → 프로세스 흐름 분석', '프로세스 분류 → 프로세스 흐름 분석 → 분석요건 식별 → 분석요건 정의', '분석요건 식별 → 프로세스 분류 → 프로세스 흐름 분석 → 분석요건 정의', '분석요건 식별 → 분석요건 정의 → 프로세스 분류 → 프로세스 흐름 분석', 2, '상향식 접근은 프로세스 분류 → 프로세스 흐름 분석 → 분석요건 식별 → 분석요건 정의 순으로 진행된다.', 100081, 'cbt'),
    (82, 2, '분석 수준진단', '데이터 분석 수준진단 결과에서 기업에 필요한 데이터 및 분석기법은 부족하지만 조직의 준비도가 높은 단계는?', '확산형', '도입형', '준비형', '정착형', 2, '도입형은 분석업무·기법은 부족하나 조직·인력의 준비도는 높은 단계이다.', 100082, 'cbt'),
    (83, 3, '척도', '스피어만 상관분석으로 분석할 수 없는 척도는?', '명목척도', '등간척도', '비율척도', '서열척도', 1, '스피어만 상관분석은 순위(서열)를 이용하는 방법으로, 순위를 매길 수 없는 명목척도에는 적용할 수 없다.', 100083, 'cbt'),
    (84, 3, '표본추출', '모집단 개체에 1, 2, 3, …, n과 같은 일련번호를 부여한 후 첫 번째 표본으로부터 일정 간격으로 표본을 선택하는 추출법은?', '단순무작위추출', '계통추출', '층화추출', '집락추출', 2, '일련번호를 부여하고 일정 간격으로 표본을 뽑는 방법은 계통추출(systematic sampling)이다.', 100084, 'cbt'),
    (85, 3, '연관분석', '연관분석의 장점이 아닌 것은?', '조건반응(If-then) 기반으로 분석결과 해석이 쉽다.', '목적 없어도 분석 가능하다.', '데이터를 변환하지 않고 그대로 사용할 수 있어 간편하다.', '비슷한 것은 묶어서 분석하면 계산량이 기하급수적으로 증가하는 것을 막을 수 있다.', 4, '연관분석은 품목 조합이 늘어날수록 계산량이 기하급수적으로 증가하는 단점이 있으며, 이를 자동으로 막아주는 기능은 없다.', 100085, 'cbt'),
    (86, 3, 'k-NN', 'k-NN 알고리즘의 특징 중 틀린 것은?', '사전 학습 없이 새 데이터 분류가 가능하다.', '가까운 그룹을 찾는다.', '가까운 k개 데이터를 탐색한다.', 'k 개수가 클수록 과대적합 문제가 발생할 수 있다.', 4, 'k-NN은 k가 클수록 결정 경계가 완만해져 과소적합 위험이 커지고, k가 작을수록 과대적합 위험이 커진다.', 100086, 'cbt'),
    (87, 3, '비모수검정', '비모수검정으로 적절하지 않은 것은?', '윌콕슨 순위합 검정', 'run 검정', '만-휘트니 검정', 't-검정', 4, 't-검정은 모집단이 정규분포를 따른다고 가정하는 모수적 검정 방법이다.', 100087, 'cbt'),
    (88, 3, '중심극한정리', '중심극한정리에 대한 설명으로 잘못된 것은?', '표본의 크기가 커질수록 정규분포에 따른다.', '표본평균에 관한 설명이다.', '모집단이 정규분포를 따라야 한다.', '모집단이 비대칭일수록 표본의 크기가 커야 한다.', 3, '중심극한정리는 모집단의 분포 형태와 관계없이 표본크기가 커지면 표본평균의 분포가 정규분포에 근사한다는 정리이다.', 100088, 'cbt'),
    (89, 3, '시계열 정상화', '시계열데이터를 정상화하는 방법 중 적절하지 않은 것은?', '차분', '정규화', '이상치 제거', '구간분할', 2, '정규화(Normalization)는 값의 스케일을 조정하는 기법으로, 추세·계절성을 제거해 정상성을 확보하는 방법이 아니다.', 100089, 'cbt'),
    (90, 3, '연관분석 신뢰도', '우유를 구매한 사람이 커피도 구매할 신뢰도는? (우유 구매: 10건, 우유·커피 동시 구매: 30건)', '0.65', '0.7', '0.75', '0.8', 3, '신뢰도(우유→커피) = P(우유∩커피)/P(우유) = 30/(10+30) = 0.75이다.', 100090, 'cbt'),
    (91, 3, '시계열 분해요인', '시계열데이터 분석에 대한 설명으로 적절하지 않은 것은?', '추세요인: 일정한 방향으로 상승 또는 하락하는 경향을 보이는 요인', '계절요인: 일정한 주기를 가지는 상하 반복의 규칙적인 변동의 요인', '순환요인: 알려진 주기 또는 고정된 주기로 반복되는 요인', '불규칙요인: 설명할 수 없는 오차에 해당되는 요인', 3, '고정된 주기로 반복되는 요인은 계절요인이며, 순환요인은 경기변동처럼 주기가 일정하지 않은 변동 요인이다.', 100091, 'cbt'),
    (92, 3, '조건부확률', '남학생(사과 30, 딸기 40), 여학생(사과 10, 딸기 20)일 때, 전체에서 1명을 뽑았을 때 그 학생이 남학생인 경우 사과를 좋아할 확률은?', '3/5', '7/10', '3/4', '3/7', 4, 'P(사과|남학생) = 남학생 중 사과 선호(30) / 남학생 전체(30+40=70) = 3/7이다.', 100092, 'cbt'),
    (93, 3, 'Apriori 알고리즘', 'Apriori 알고리즘의 수행 순서로 올바르게 나열한 것은? (가: 최소지지도 설정, 나: 2가지 품목 찾기, 다: 개별품목 중 최소지지도 넘는 품목 찾기, 라: 반복 수행하여 빈발품목집합 찾기)', '가-나-라-다', '가-다-나-라', '다-가-나-라', '다-나-가-라', 2, 'Apriori는 최소지지도 설정(가) → 개별 품목 중 기준을 넘는 품목 탐색(다) → 조합을 늘려가며 빈발항목집합 탐색(나) → 반복 수행(라) 순으로 진행된다.', 100093, 'cbt'),
    (94, 3, '요약변수', '요약변수의 특징 중 틀린 것은?', '많은 모델에서 공통으로 사용할 수 있어 재활용 가능성이 높다.', '수집된 정보를 분석에 맞게 종합한 것이다.', '특정 조건을 만족하거나 특정 함수에 의해 값을 만들어 의미를 부여한 변수이다.', '데이터마트에서 중요한 변수이다.', 3, '특정 조건이나 함수로 새로운 의미를 부여해 만든 변수는 파생변수이며, 요약변수는 기존 정보를 종합·요약한 변수이다.', 100094, 'cbt'),
    (95, 3, '다중공선성', '회귀분석의 독립변수들 간에 강한 상관관계가 나타나는 문제를 의미하는 것은?', '다중공선성', '회귀계수', '선형계수', '상관계수', 1, '독립변수 간 강한 상관관계로 회귀계수 추정이 불안정해지는 현상을 다중공선성이라 한다.', 100095, 'cbt'),
    (96, 3, '거리 측정', '두 변수의 상관관계가 클 때 유사도 거리를 측정하는 방법은?', '맨하탄거리', '유클리디안거리', '표준화거리', '마할라노비스거리', 4, '마할라노비스 거리는 변수 간 상관관계(공분산)를 반영하여 거리를 계산하는 방법이다.', 100096, 'cbt'),
    (97, 3, '주성분분석', '주성분분석에 대한 설명으로 잘못된 것은?', '차원축소 기능이 있다.', '차원축소로 예측에도 활용이 가능하다.', '변수 간 선형관계를 알아보기 위한 분석이다.', '주성분 간에는 상관관계가 없다.', 3, '주성분분석의 목적은 변수 간 선형관계 파악이 아니라, 분산을 최대한 보존하며 차원을 축소하는 것이다.', 100097, 'cbt'),
    (98, 3, 'K-means', 'K-means 군집분석을 활용할 수 있는 그래프는?', '오차제곱합 그래프', 'ROC 그래프', '집단 내 제곱합 그래프', '향상도 곡선', 3, '적정 군집 수(k)를 정할 때는 군집 내 제곱합(WSS)의 변화를 나타낸 엘보우 그래프를 활용한다.', 100098, 'cbt'),
    (99, 3, '확률', '확률 관련 내용 중 잘못 설명한 것은?', '두 사건이 독립일 때 동시에 나올 확률은 A사건과 B사건 확률의 합이다.', '한 사건 A가 일어날 확률을 P(A)라 할 때, n번의 반복시행에서 사건 A가 일어난 횟수를 r이라 하면, 상대도수 r/n은 n이 커짐에 따라 확률 P(A)에 가까워진다.', '두 사건이 독립일 때 교집합의 확률은 두 사건의 곱과 동일하다.', '조건부 확률을 이용해 사전확률과 사후확률로 계산하는 것은 베이즈 이론이다.', 1, '두 사건이 독립일 때 동시에 일어날 확률은 두 확률의 곱(P(A)×P(B))이며, 합이 아니다.', 100099, 'cbt'),
    (100, 3, '군집분석', '한 군집 내의 다른 데이터를 분석해도 동일한 결과가 나오는 특성은?', '다양성', '일반화', '효율성', '예측분석의 정확성', 2, '같은 군집 내 어떤 데이터를 사용해도 동일한 결과가 나온다는 것은 그 군집이 대표성을 갖고 일반화될 수 있음을 의미한다.', 100100, 'cbt'),
    (101, 3, '척도', '척도에 대한 내용으로 올바르게 짝지어진 것은?', '시험점수는 명목척도이다.', '고객만족도 5점 척도는 비율척도이다.', '고향이 수도권/비수도권인지는 명목척도이다.', '몸무게 또는 나이는 명목척도이다.', 3, '수도권/비수도권처럼 이름으로만 구분되는 범주는 명목척도이다. 몸무게·나이는 비율척도, 만족도 점수는 보통 서열척도로 본다.', 100101, 'cbt'),
    (102, 3, '범주형자료분석', '범주형 자료분석에 대한 설명 중 틀린 것은?', '범주형 변수의 빈도를 비교할 때는 교차표를 활용할 수 있다.', '적합도 검정은 수치형 변수의 정규성을 확인하는 데 사용된다.', '카이제곱검정은 기대빈도와 관측빈도의 차이를 검정하는 방법이다.', '적합도 검정은 도수표 내 관찰도수의 분산과 기대도수 분산이 얼마나 일치하는지를 검정한다.', 4, "적합도 검정은 범주형 자료의 관측도수(빈도)가 기대도수와 얼마나 일치하는지를 직접 비교하는 검정으로, '분산의 일치'를 검정한다는 설명은 적절하지 않다.", 100102, 'cbt'),
    (103, 3, '기술통계', '기술통계와 관련된 설명 중 틀린 것은?', '결측치를 모두 0으로 변환하여 평균을 계산한다.', '기술통계는 데이터를 요약하고 설명하는 데 사용된다.', '대표값으로는 평균, 중앙값, 최빈값 등이 있다.', '산포도는 데이터의 분포 범위를 파악할 수 있는 도구이다.', 1, '결측치를 임의로 0으로 대체하면 평균이 왜곡되므로 적절한 처리 방법이 아니다.', 100103, 'cbt'),
    (104, 3, '시계열 정상화', '시계열데이터의 정상성을 확보할 수 있는 방법으로 옳은 것은?', '더미변수화', '정규화', '차분', '군집화', 3, '추세나 분산의 변화를 제거해 정상성을 확보하는 대표적 방법은 차분이다.', 100104, 'cbt'),
    (105, 3, '시계열 분해요인', '시계열 분해에 대한 설명 중 틀린 것은?', '불규칙요인은 예측이 어렵고 설명되지 않는 요인이다.', '순환요인은 경제나 자연현상 등 주기적인 원인으로 설명된다.', '계절요인은 고정된 주기를 가지고 나타나는 요인이다.', '추세는 시간에 따라 데이터가 증가하거나 감소하는 패턴이다.', 2, '순환요인은 경기변동처럼 알려진 고정 주기가 없는 변동이며, 고정된 주기를 갖는 것은 계절요인이다.', 100105, 'cbt'),
    (106, 3, '회귀분석 가정', '선형회귀분석의 가정에 대한 설명 중 틀린 것은?', '정규성: 잔차의 분포가 정규분포를 따른다.', '독립성: 독립변수 간에는 서로 관련이 없다.', '등분산성: 모든 독립변수 잔차분포에는 동일한 분산을 가진다.', '선형성: 독립변수와 종속변수 간에는 선형관계가 있다.', 2, '회귀분석의 독립성 가정은 잔차(오차)들이 서로 독립이라는 것이며, 독립변수끼리 관련이 없다는 뜻이 아니다.', 100106, 'cbt'),
    (107, 3, '변수선택법', '독립변수 후보 모두를 포함한 모형에서 변수를 하나씩 제거하는 변수선택법은?', '후진제거법', '단계별선택법', '교차검증법', '전진선택법', 1, '모든 변수를 포함한 완전모형에서 유의하지 않은 변수를 하나씩 제거해 나가는 방법이 후진제거법이다.', 100107, 'cbt'),
    (108, 3, '상관계수', '상관계수에 대한 설명 중 틀린 것은?', '상관계수는 -1에서 1 사이 값을 가진다.', '상관계수가 0일 경우, 직선상관관계가 없다.', '상관계수가 -1일 경우, 상관관계가 가장 약하다.', '상관계수는 두 변수 간의 직선관계를 측정한다.', 3, '상관계수가 -1에 가까울수록 완전한 음의 선형관계로, 상관관계가 가장 강한 경우이다.', 100108, 'cbt'),
    (109, 3, '모델평가지표', '모델이 참이라고 예측한 것 중에서 실제로도 참인 것의 비율은?', '정밀도', '정확도', '재현율', 'F1점수', 1, '정밀도(Precision)는 모델이 양성(참)으로 예측한 것 중 실제로 양성인 비율이다.', 100109, 'cbt'),
    (110, 3, '거리 측정', '연속형 변수 간의 유사성 또는 거리를 측정하는 방법으로 적절하지 않은 것은?', '맨하탄거리', '자카드거리', '마할라노비스거리', '유클리디안거리', 2, '자카드 거리는 집합(주로 범주형·이진 데이터)의 유사도를 측정하는 방법으로 연속형 변수에는 적절하지 않다.', 100110, 'cbt'),
    (111, 3, 'ROC 곡선', 'ROC 곡선으로 가장 효율적인 도형을 이끌어냈을 때의 X, Y 좌표값은?', '(0, 0)', '(1, 0)', '(0, 1)', '(1, 1)', 3, 'ROC 곡선에서 (0, 1)은 위양성률이 0이고 민감도가 1인 좌상단 점으로, 가장 이상적인 분류 성능을 의미한다.', 100111, 'cbt'),
    (112, 3, '배깅과 부스팅', '앙상블 기법인 배깅(Bagging)과 부스팅(Boosting)에 대한 설명으로 적절한 것은?', '배깅은 모델 간 상호의존성을 강조한다.', '배깅은 약한 학습기를 순차적으로 학습시킨다.', '부스팅은 오버샘플링을 통해 데이터 수를 증가시킨다.', '부스팅은 잘못 분류된 데이터에 더 큰 가중치를 부여한다.', 4, '부스팅은 이전 모델이 잘못 분류한 데이터에 더 큰 가중치를 부여하며 순차적으로 학습을 보완해 나간다.', 100112, 'cbt'),
    (113, 3, '인공신경망', '인공신경망 모형에 대한 설명으로 틀린 것은?', '예측정확도가 높다.', '설명력 있는 가중치를 산출할 수 있다.', '복잡한 패턴을 스스로 학습할 수 있다.', '다양한 비정형 데이터를 처리할 수 있다.', 2, '인공신경망은 내부 가중치의 의미를 해석하기 어려운 블랙박스 모형으로, 설명력 있는 가중치를 제공한다고 보기 어렵다.', 100113, 'cbt'),
    (114, 3, '로지스틱회귀', '로지스틱회귀분석의 적용 사례로 적절한 것은?', '주택가격 예측', '제품수명 예측', '마케팅 성공여부 예측', '키와 몸무게의 상관관계 분석', 3, '로지스틱회귀는 성공/실패와 같은 이진분류 문제에 사용되며, 마케팅 성공 여부 예측이 대표적 사례이다.', 100114, 'cbt'),
    (115, 3, '의사결정나무', '의사결정나무에 대한 설명으로 틀린 것은?', '가지치기를 통해 과적합을 방지할 수 있다.', '자식마디의 순수도가 증가하도록 분류나무를 형성한다.', '지니지수나 엔트로피를 기준으로 분할한다.', '가지치기를 통해 학습 데이터셋에서의 정확도를 높일 수 있다.', 4, '가지치기는 학습데이터에 대한 과적합을 줄여 일반화 성능을 높이는 것이 목적이며, 오히려 학습데이터 정확도는 낮아질 수 있다.', 100115, 'cbt'),
    (116, 3, 'K-means', 'K-means에 대한 설명으로 틀린 것은?', '비지도학습에 속하는 군집 알고리즘이다.', '군집 개수 k를 알고리즘이 자동으로 선택해준다.', '클러스터의 중심점을 기준으로 군집을 형성한다.', '반복적으로 중심점을 재계산하며 수렴한다.', 2, 'K-means는 군집 개수 k를 사용자가 사전에 직접 지정해야 하며, 알고리즘이 자동으로 정해주지 않는다.', 100116, 'cbt'),
    (117, 3, 'SOM', 'SOM(자기조직화지도)에 대한 설명 중 틀린 것은?', 'SOM은 경쟁학습 기반의 신경망이다.', '차원을 축소해 시각화에 활용할 수 있다.', '입력벡터와 가장 가까운 노드를 BMU라 한다.', '부분적으로(locally) 연결된다.', 4, 'SOM은 격자 구조의 모든 노드가 경쟁학습에 참여하는 방식으로, 국소적으로만 연결된다고 보기 어렵다.', 100117, 'cbt'),
    (118, 3, '연관분석 지지도', '연관분석에서 A→B일 경우, 지지도(Support)에 해당하는 것은?', 'A가 나왔을 때 B도 나올 확률', '전체 중에서 A와 B가 동시에 구매될 확률', 'A가 발생한 경우 중 B도 발생한 비율', 'B가 발생한 경우 중 A도 발생한 비율', 2, '지지도는 전체 거래 중 A와 B가 동시에 포함된 거래의 비율 P(A∩B)이다.', 100118, 'cbt'),
    (119, 3, '군집분석', '군집분석에 대한 설명 중 틀린 것은?', '비지도학습의 한 형태이다.', 'K-means는 대표적인 군집화 기법이다.', '입력변수가 범주형일 경우 군집분석을 할 수 없다.', '유클리디안 거리 등을 이용해 유사도를 측정할 수 있다.', 3, '범주형 변수도 자카드 거리, k-modes 등 적절한 유사도 척도를 사용하면 군집분석이 가능하다.', 100119, 'cbt'),
    (120, 3, '다차원척도법', '다차원척도법(MDS)에 대한 설명으로 틀린 것은?', '절대적 위치를 알 수 있다.', '변수 간 거리 정보를 시각화한다.', '변수 간 유사성을 직관적으로 파악할 수 있다.', '데이터 구조를 2차원이나 3차원으로 축소해 표현할 수 있다.', 1, 'MDS는 개체 간 상대적 거리(유사성)만 보존해 저차원에 배치하는 기법으로, 절대적 위치를 알려주지는 않는다.', 100120, 'cbt'),
    (121, 3, '상관분석', '스피어만·피어슨 상관분석에 대한 설명으로 가장 부적절한 것은?', '스피어만은 범주형 변수의 선형관계를 설명한다.', '피어슨 상관계수는 연속형 변수 간의 선형관계를 분석할 때 사용된다.', '스피어만 상관계수는 서열형(순위형) 변수 간의 관계를 분석할 때 사용된다.', '스피어만 상관계수는 비선형관계도 어느 정도 설명할 수 있다.', 1, '스피어만 상관계수는 순위(서열)형 변수 간 단조관계를 분석하는 방법으로, 범주형 변수의 선형관계를 설명하는 것이 아니다.', 100121, 'cbt'),
    (122, 3, '척도', '절대적 기준인 영점(0)이 존재하는 척도는?', '명목척도', '서열척도', '등간척도', '비율척도', 4, '절대영점이 존재해 사칙연산이 모두 가능한 척도는 비율척도이다.', 100122, 'cbt'),
    (123, 3, 'EDA', '탐색적 데이터 분석(EDA)의 특징으로 적절하지 않은 것은?', '데이터의 전반적인 구조를 파악하고 이상치 및 결측치를 발견하는 단계이다.', '동일한 분석 결과를 얻기 위해 재현성을 검증하는 단계이다.', '상관관계 분석 및 시각화를 통해 종속변수에 영향을 주는 주요 독립변수를 탐색한다.', '변수의 개수, 데이터 타입 및 기초통계량(평균, 중앙값)을 확인하는 단계이다.', 2, 'EDA는 데이터의 구조·이상치·패턴을 탐색하는 단계이며, 분석 결과의 재현성을 검증하는 것은 EDA의 목적이 아니다.', 100123, 'cbt'),
    (124, 3, '가설검정 오류', '가설검정의 제1종 및 2종 오류 해석에 대한 설명으로 적절하지 않은 것은?', '제1종 오류는 귀무가설이 실제로는 참인데도 불구하고, 이를 기각하고 대립가설을 채택하는 오류이다.', '제2종 오류는 실제로는 대립가설이 참인데도 불구하고, 귀무가설을 기각하지 못하고 채택하는 통계적 오류이다.', '유의수준(α)은 제1종 오류의 최소 허용한계이다.', '유의수준을 너무 작게 설정하면 2종 오류를 범할 확률이 높아진다.', 3, '유의수준(α)은 제1종 오류를 범할 수 있는 최대 허용한계이며, 최소 허용한계가 아니다.', 100124, 'cbt'),
    (125, 3, '표본조사', '표본조사에 대한 설명으로 적절하지 않은 것은?', '표본오차는 표본이 모집단을 완벽히 대표하지 못해 생기는 오차이다.', '표본의 크기가 커질수록 표본오차는 0에 가까워진다.', '표본추출을 통해 비표본오차를 최소화할 수 있다.', '비표본오차는 표본의 크기나 추출방법에 관계없이 발생 가능하다.', 3, '비표본오차는 조사·입력·집계 과정의 실수 등에서 발생하는 오차로, 표본추출 방법을 통해 줄일 수 있는 것이 아니다.', 100125, 'cbt'),
    (126, 3, '분포의 대표값', '오른쪽으로 꼬리가 긴(right-skewed) 분포에서 왼쪽부터 최빈값, 중앙값, 평균 순서로 나타나는 것이 옳은가?', '최빈값-평균-중앙값', '최빈값-중앙값-평균', '평균-중앙값-최빈값', '중앙값-최빈값-평균', 2, '오른쪽 꼬리가 긴 분포는 최빈값 < 중앙값 < 평균 순서로 나타난다.', 100126, 'cbt'),
    (127, 3, '표본추출', '표본추출방법에 대한 설명으로 적절하지 않은 것은?', '단순무작위추출법: 표본선택확률을 모두 동일하게 무작위로 표본을 추출한다.', '계통추출법: 일련번호를 부여한 각 개체를 일정한 간격으로 나누고 각 구간에서 무작위 추출하는 방법이다.', '집략추출법: 모집단에서 집단을 일차적으로 표집한 다음, 선정된 각 집단에서 구성원을 표본으로 추출하는 다단계 표집방법이다.', '층화추출법: 모집단을 서로 중복되지 않는 집단 및 층(strata)으로 구분하고 각 집단 내에서 표본을 무작위 추출한다.', 2, '계통추출법은 첫 표본을 무작위로 정한 뒤 일정한 간격으로 순차적으로 추출하는 방법이며, 구간별 무작위 추출과는 다르다.', 100127, 'cbt'),
    (128, 3, '통계적 유의성', '통계적 유의성에 대한 설명으로 적절하지 않은 것은?', '표본의 크기가 커질수록 표준오차가 작아지므로, 신뢰구간의 길이는 점점 짧아진다.', 'p-value가 클수록 귀무가설을 기각하고 대립가설을 채택할 확률이 높아진다.', '표본의 크기가 커질수록 아주 작은 차이도 통계적으로 유의미하게 나타날 가능성이 높아진다.', '신뢰수준을 95%에서 99%로 높이면 신뢰구간의 폭은 더 넓어지고, 정밀도는 떨어진다.', 2, 'p-value가 클수록 귀무가설을 기각할 근거가 약해지므로, 오히려 귀무가설을 기각하지 못할 가능성이 높아진다.', 100128, 'cbt'),
    (129, 3, '회귀분석', '단순회귀모형에서 SSE가 20이고 표본이 10개(단순회귀, k=1)라면 MSE는 얼마인가?', '2', '2.22', '2.5', '30', 3, 'MSE = SSE/(n-k-1) = 20/(10-1-1) = 20/8 = 2.5이다.', 100129, 'cbt'),
    (130, 3, '다중공선성', '다중회귀분석에서 다중공선성을 해결할 수 있는 방안으로 적절하지 않은 것은?', '라쏘회귀(Lasso)', '릿지회귀(Ridge)', '엘라스틱넷회귀(Elastic Net)', '로지스틱회귀(Logistic)', 4, '라쏘·릿지·엘라스틱넷은 규제를 통해 다중공선성을 완화하는 방법이지만, 로지스틱회귀는 종속변수가 범주형일 때 쓰는 모델로 다중공선성 해결책이 아니다.', 100130, 'cbt'),
    (131, 3, '다중공선성', '다중회귀분석에서 다중공선성에 대한 설명으로 적절하지 않은 것은?', '다중공선성이 존재하더라도 회귀계수의 분산은 항상 동일하다.', '독립변수 간 높은 상관관계로 회귀계수 추정이 불안정해진다.', '다중공선성은 VIF 지표로 측정 가능하다.', '높은 상관관계를 갖는 설명변수를 모형에서 제거하여 해결 가능하다.', 1, '다중공선성이 있으면 회귀계수의 분산(표준오차)이 커져 추정이 불안정해지므로, 분산이 항상 동일하다는 설명은 틀렸다.', 100131, 'cbt'),
    (132, 3, '시계열분석', '시계열분석에 대한 설명으로 적절하지 않은 것은?', '비정상 시계열인 경우 차분 및 변환을 통해 정상성을 확보할 수 있다.', '정상 시계열인 경우 자기회귀(AR) 또는 이동평균(MA) 모형을 적용할 수 있다.', '백색잡음(White noise)은 대표적인 비정상 시계열이다.', '정상성 확보를 위해 평균이 일정하지 않으면 차분을, 분산이 일정하지 않으면 변환이 사용된다.', 3, '백색잡음은 평균과 분산이 일정한 대표적인 정상 시계열이다.', 100132, 'cbt'),
    (133, 3, '상관계수', '변수 간의 비선형관계를 분석할 수 있는 지표는?', '피어슨 상관계수', '스피어만 상관계수', '코사인 유사도', '자카드 계수', 2, '스피어만 상관계수는 순위를 기반으로 하여 단조적인 비선형관계도 어느 정도 설명할 수 있다.', 100133, 'cbt'),
    (134, 3, 'ARIMA', 'ARIMA 모델에 대한 설명으로 적절하지 않은 것은?', 'ARIMA(p, d, q) 형태로 표현되며 p, d, q는 각각 자기회귀 차수, 차분 차수, 이동평균 차수를 의미한다.', '일반적으로 자기회귀 차수를 먼저 정하고, 차분 차수를 정한다.', '시계열 데이터의 과거값과 오차를 이용해 미래를 예측하는 통계모델이다.', '데이터를 정상 시계열로 변환하여 분석하므로 통계적 안정성이 높다.', 2, 'ARIMA 모형링 시에는 먼저 차분(d)으로 정상성을 확보한 뒤 자기회귀(p)·이동평균(q) 차수를 정하는 것이 일반적인 순서이다.', 100134, 'cbt'),
    (135, 3, '앙상블', '앙상블 학습에 대한 설명으로 적절하지 않은 것은?', '배깅(Bagging)은 복원추출 기반의 부트스트랩 샘플을 생성하여 각 샘플마다 학습시킨 후 모든 모델의 예측 결과를 하나로 합치는 방식이다.', '부스팅(Boosting)은 개별 모델에 동일한 가중치를 부여하여 순차적으로 학습한다.', '보팅(Voting)은 각 모델 예측 결과 중 가장 많이 나온 결과를 최종 결과로 채택한다.', '랜덤포레스트(Random Forest)는 배깅 방식을 기반으로 하여 복수의 독립적인 의사결정나무를 생성 후 예측을 수행한다.', 2, '부스팅은 이전 단계에서 잘못 분류된 데이터에 더 큰 가중치를 부여하며 순차적으로 학습하므로, 동일한 가중치를 부여한다는 설명은 틀렸다.', 100135, 'cbt'),
    (136, 3, '활성화함수', '입력층이 직접 출력층으로 연결되고 출력층의 노드가 1개인 인공신경망에서 사용하면 로지스틱회귀모형과 작동 원리가 동일해지는 활성화함수는?', 'Sigmoid', 'Tanh', 'ReLU', 'Softmax', 1, '시그모이드 함수는 출력을 0~1 사이 확률값으로 변환하며, 단일 출력 노드 신경망에 적용하면 로지스틱회귀와 동일한 원리로 작동한다.', 100136, 'cbt'),
    (137, 3, '혼동행렬', '혼동행렬에서 TP=200, FN=400, FP=100, TN=300일 때 민감도(Sensitivity)는?', '0.33', '0.5', '0.75', '0.8', 1, '민감도 = TP/(TP+FN) = 200/(200+400) = 0.33이다.', 100137, 'cbt'),
    (138, 3, 'EM 알고리즘', '혼합분포 군집모델에서 최대가능도 추정을 보완하기 위해 사용되는 분석기법은?', 'K-NN 알고리즘', 'K-평균 알고리즘', 'Apriori 알고리즘', 'EM 알고리즘', 4, '혼합분포 군집(가우시안 혼합모델 등)에서는 잠재변수를 다루기 위해 EM(기대값 최대화) 알고리즘을 사용한다.', 100138, 'cbt'),
    (139, 3, '군집분석', '군집분석 기법에 대한 설명으로 적절하지 않은 것은?', 'DBSCAN은 밀도기반 군집화 방식으로 초기 중심값 설정이 불필요하다.', '가우시안 혼합모델(GMM)은 EM 알고리즘을 사용하여 모델 매개변수를 추정하며, 초기 중심값 설정에 따라 그 결과가 달라질 수 있다.', '자기조직화지도(SOM)는 비지도학습으로 차원축소와 군집화를 동시에 수행한다.', '자기조직화지도(SOM)는 모든 입력 노드에 동일한 수의 데이터가 할당된다.', 4, 'SOM은 경쟁학습 방식으로 노드별 할당 데이터 수가 균등하다는 보장이 없다.', 100139, 'cbt'),
    (140, 3, '군집분석', '군집 내 오차제곱합(SSE)을 최소화하는 방식으로 군집을 수행하는 연결법은?', '중심연결법', '평균연결법', '와드연결법', '단일연결법', 3, "와드연결법(Ward's method)은 군집을 병합할 때 군집 내 오차제곱합(SSE)의 증가가 최소가 되는 방향으로 병합한다.", 100140, 'cbt'),
    (141, 3, '연관분석 지지도', "커피 20건, 우유 50건, 커피+우유 동시 구매 30건, 전체 거래 100건일 때 '우유→커피'의 지지도는?", '0.2', '0.3', '0.4', '0.5', 2, '지지도 = P(우유∩커피) = 30/100 = 0.3이다.', 100141, 'cbt'),
    (142, 3, '상자그림', '상자그림(Boxplot)에 대한 설명으로 적절하지 않은 것은?', '상자그림 내부의 수평선은 해당 데이터의 중앙값을 나타낸다.', '사분위수범위(IQR)는 전체 데이터의 50%가 분포하는 구간의 길이를 나타낸다.', 'IQR의 1.5배를 초과하여 벗어난 관측치는 이상치로 정의할 수 있다.', '상자그림의 폭과 길이 비교를 통해 해당 데이터의 관측치 개수를 파악할 수 있다.', 4, '상자그림은 사분위수·이상치 등 분포의 특성을 보여줄 뿐, 관측치의 개수를 직접 알려주지는 않는다.', 100142, 'cbt'),
    (143, 3, '이상값 처리', '데이터 이상값 탐지 및 처리 방법에 대한 설명으로 적절하지 않은 것은?', '상자그림에서 사분위수범위(IQR)의 1.5배를 기준으로 상한 및 하한 임계치를 설정하여 이상값을 식별한다.', '데이터가 정규분포를 따른다고 가정할 때, 평균으로부터 표준편차의 3배 이상 떨어진 값을 이상값으로 판단한다.', '표본평균의 표준오차 범위를 계산하여 해당 범위를 벗어나는 값을 이상값으로 처리한다.', '이상값을 삭제하는 대신 경우에 따라 평균, 중앙값 또는 회귀분석을 통한 예측값으로 바꾸어 데이터의 손실을 최소화할 수 있다.', 3, '표준오차는 표본평균의 변동성을 나타내는 지표로, 개별 관측치의 이상값 판정 기준으로 쓰이는 방법이 아니다.', 100143, 'cbt'),
    (144, 3, '통계적 추론', '통계적 추론에 대한 설명으로 적절하지 않은 것은?', '구간추정 방식으로 일정한 신뢰수준 하에서 모수가 포함될 것으로 기대되는 범위를 정하여 모수를 추정할 수 있다.', '가설검정 시 사용되는 검정통계량은 하나의 단일 통계값으로 산출하여 판단한다.', '유의수준은 제1종 오류를 범할 수 있는 허용한계로 가설 채택 여부를 결정하는 값이다.', 'p-value 값이 유의수준보다 작으면 귀무가설을 기각할 수 있다.', 2, '가설검정에서는 검정통계량뿐 아니라 그에 대응하는 p-value·기각역 등을 함께 고려해 판단하므로, 단일 통계값만으로 판단한다는 설명은 지나치게 단순화된 틀린 설명이다.', 100144, 'cbt'),
    (145, 3, '회귀분석 적합성', '회귀분석 모형 적합성을 판단하는 설명으로 적절하지 않은 것은?', '회귀모형의 적합성을 판단하기 위해 잔차산점도를 확인하며, 잔차가 특정 패턴 없이 무작위로 분포해야 모형의 가정이 충족된 것으로 본다.', '다중회귀분석에서는 독립변수의 수가 늘어나면 결정계수가 무의미하게 높아지는 단점을 보완하기 위해 수정된 결정계수를 평가지표로 활용하기도 한다.', '회귀계수의 유의성은 t-검정으로 판단 가능하며, 해당 독립변수가 종속변수를 설명하는 데 유의미한지 확인 가능하다.', '설명변수 간 상관계수를 확인하면 해당 회귀분석모형의 적합성을 판단할 수 있다.', 4, '설명변수 간 상관계수 확인은 다중공선성 점검에 쓰이는 것으로, 모형 자체의 적합성 판단과는 다른 목적이다.', 100145, 'cbt'),
    (146, 3, '척도', '절대영점이 존재하지 않아 덧셈, 뺄셈 등의 양적 비교는 가능한 척도는?', '명목척도', '구간척도', '비율척도', '서열척도', 2, '구간척도는 절대영점은 없지만 값 사이의 간격이 균등해 덧셈·뺄셈 등의 연산이 가능하다.', 100146, 'cbt'),
    (147, 3, '가설검정', '가설검정에 대한 설명으로 적절하지 않은 것은?', 'p-value가 미리 설정한 유의수준보다 작으면 귀무가설을 기각하고 대립가설을 채택한다.', '귀무가설이 참이라는 가정하에 검정통계량의 값이 나타날 가능성이 작을수록 귀무가설을 채택한다.', '제2종 오류는 대립가설이 실제로 참임에도 불구하고, 귀무가설을 기각하지 못하고 채택하는 오류를 의미한다.', '검정력은 대립가설이 참일 때 이를 올바르게 판정하여 귀무가설을 기각할 확률로, 1-β로 계산한다.', 2, "귀무가설 하에서 관측값이 나타날 가능성이 작을수록 그 값은 우연이라 보기 어려우므로 귀무가설을 '기각'해야 하며, 채택하는 것이 아니다.", 100147, 'cbt'),
    (148, 3, '교차분석', '교차분석에 대한 설명으로 적절하지 않은 것은?', '통상적으로 관측빈도와 기대빈도의 차이를 측정하는 카이제곱통계량을 사용한다.', '독립성검정은 두 범주형 변수 간에 서로 관련이 있는지, 아니면 통계적으로 서로 독립적인지 판단하기 위해 수행된다.', '동질성검증은 서로 다른 관찰집단 간에 해당 변수의 분포가 동일한지를 확인하기 위해 수행된다.', '교차분석은 두 변수가 연속형 변수인 경우에도 분석이 가능하다.', 4, '교차분석(카이제곱검정)은 범주형 변수를 대상으로 하는 분석으로, 연속형 변수에는 적용하기 어렵다.', 100148, 'cbt'),
    (149, 3, '상관계수', '변수 X와 Y의 상관계수가 0.5일 때, 다음 중 옳은 설명은?', '(X+0.3)과 Y의 상관계수는 0.8이다.', '(2X)와 Y의 상관계수는 1이다.', '(X+0.3)과 (Y+0.2)의 상관계수는 0.5이다.', '(-X)와 (-2Y)의 상관계수는 1이다.', 3, '상관계수는 각 변수를 이동(평행이동)해도 값이 변하지 않으므로 (X+0.3, Y+0.2)의 상관계수도 그대로 0.5이다.', 100149, 'cbt'),
    (150, 3, '회귀분석 잔차도', '회귀분석에 따른 잔차도가 특정 곡선 패턴(비선형 패턴)을 보일 때, 해당 분석의 해석으로 옳은 것은?', '잔차가 0을 중심으로 고르게 분포하므로 회귀모형이 적합하다.', '릿지, 라쏘 모델을 사용하여 해당 분석 결과의 과적합 문제를 해결해야 한다.', '독립변수와 종속변수 간 비선형성이 확인되어 비선형모델을 적용해야 한다.', '해당 잔차도 그래프는 변수에 이상치(outlier)가 많아서 발생한 패턴이다.', 3, '잔차가 특정한 패턴(곡선 형태)을 보이면 선형모형의 가정이 위배된 것으로, 독립변수와 종속변수 간 비선형관계를 의심하고 비선형모델 적용을 고려해야 한다.', 100150, 'cbt'),
    (151, 3, '통계적 추론', '통계적 추론에 대한 설명으로 적절하지 않은 것은?', '통계적 추론은 표본통계량을 토대로 모집단의 모수를 추측하는 과정이다.', '신뢰수준은 주어진 신뢰구간에 모수가 포함할 확률이다.', '표본의 크기가 일정할 때, 신뢰수준을 높이면 신뢰구간의 길이는 더 길어진다.', '신뢰수준이 일정할 때, 표본의 크기가 커질수록 신뢰구간의 길이는 더 좁아진다.', 2, '신뢰수준은 동일한 방법으로 반복 추출했을 때 신뢰구간이 모수를 포함할 상대적 빈도(확률적 의미)를 뜻하며, 특정 신뢰구간 하나가 모수를 포함할 확률이라는 표현은 엄밀하지 않다.', 100151, 'cbt'),
    (152, 3, '주성분분석', '주성분분석에 대한 설명으로 적절하지 않은 것은?', '주성분분석을 통해 차원을 축소시켜 다중공선성 문제를 해결할 수 있다.', '제1주성분에서 제2주성분으로 숫자가 커질수록 각 주성분이 설명하는 분산의 크기도 지속 증가한다.', '제1주성분은 전체 데이터의 변동을 가장 많이 설명하는 축이다.', '일반적으로 고윳값이 1 이상인 주성분만을 선택하거나, 누적기여율이 70~90% 이상이 되는 지점까지의 주성분을 사용한다.', 2, '주성분은 번호가 커질수록(제1, 제2, …) 설명하는 분산의 크기가 점차 감소한다.', 100152, 'cbt'),
    (153, 3, '로지스틱회귀', '로지스틱회귀분석에 대한 설명으로 적절하지 않은 것은?', '로지스틱회귀모형의 연결함수로는 시그모이드 함수를 사용한다.', '합격/불합격과 같은 이진분류 문제를 해결하는 데 적합한 회귀분석이다.', '오즈(Odds)는 범주 A에 속할 확률을 범주 B에 속할 확률로 나눈 값이다.', '종속변수인 로짓(Logit)과 독립변수는 서로 선형적 관계를 가진다.', 1, '로지스틱회귀의 연결함수는 로짓(logit)함수이며, 시그모이드는 로짓의 역함수로 예측 확률을 계산할 때 쓰인다.', 100153, 'cbt'),
    (154, 3, '상관계수', '두 숫자형 변수 간의 선형관계에 대한 설명으로 적절하지 않은 것은?', '상관계수는 -1 이상, 1 이하의 값을 가지며, 1이나 -1에 가까울수록 두 변수 간의 선형관계가 강함을 의미한다.', '0에 가까운 상관계수는 두 변수 사이에 선형적인 관계가 거의 없음을 의미한다.', '높은 상관계수가 두 변수 간의 인과관계를 보장하지는 않는다.', '상관계수의 부호가 음수라면 두 변수는 서로 반비례 관계로 볼 수 있다.', 4, '상관계수가 음수인 것은 한 변수가 증가할 때 다른 변수가 감소하는 경향(음의 상관)을 의미할 뿐, 수학적 반비례(y=k/x) 관계를 뜻하는 것은 아니다.', 100154, 'cbt'),
    (155, 3, '시계열 분해요인', '분해시계열의 주요 요인(Decomposition Factors)으로 적절하지 않은 것은?', '추세요인', '규칙요인', '계절요인', '순환요인', 2, "시계열 분해의 4대 요인은 추세, 계절, 순환, 불규칙요인이며 '규칙요인'은 존재하지 않는다.", 100155, 'cbt'),
    (156, 3, '시계열 정상화', '비정상 시계열데이터를 정상 시계열로 변환하기 위해 사용되는 방법으로 적절한 것은?', '지수평활법', '선형회귀분석', '차분', '결측치 처리', 3, '추세나 분산의 변화를 제거해 정상성을 확보하는 대표적인 방법은 차분이다.', 100156, 'cbt'),
    (157, 3, '데이터 분할', '데이터 분할방식에 대한 설명으로 적절하지 않은 것은?', '훈련용 데이터는 모델이 데이터 패턴을 학습하고 가중치를 조정하는 데 사용된다.', '검증용 데이터는 모델의 과대 및 과소적합 조정 시 사용된다.', '검증용 데이터는 해당 모델의 최종 성능을 평가 시 활용된다.', '평가용 데이터는 모델의 객관적인 성능 측정을 위해 학습에 활용되지 않은 데이터이다.', 3, '모델의 최종 성능 평가에는 검증용이 아니라 평가(테스트)용 데이터가 사용된다.', 100157, 'cbt'),
    (158, 3, '의사결정나무', '의사결정나무 모델에 대한 설명으로 적절하지 않은 것은?', '데이터 분류 기준으로는 지니지수 및 엔트로피, 카이제곱통계량이 활용된다.', '연속형 변수인 경우, 의사결정나무 모형은 학습 데이터에 대해 항상 예측정확도 100%의 모델 구현이 가능하다.', '하위 노드로 내려갈수록 데이터 불순도는 점차 감소한다.', '불필요한 분기를 제거하는 가지치기를 통해 모델의 일반화 성능을 향상시킬 수 있다.', 2, '완전히 성장한 나무는 학습데이터에 과적합될 수는 있어도, 데이터 특성상 항상 100% 정확도를 보장하지는 않는다.', 100158, 'cbt'),
    (159, 3, '활성화함수', '인공신경망모형에서 입력층에서 전달된 신호의 합을 출력값으로 변환하여 다음 층으로 전달하는 함수는?', '연결함수', '활성화함수', '출력함수', '가중치함수', 2, '입력 신호의 가중합을 비선형 출력값으로 변환해 다음 층에 전달하는 함수는 활성화함수이다.', 100159, 'cbt'),
    (160, 3, '모델평가지표', '정밀도(Precision)와 재현율(Recall)의 조화평균으로 계산되며, 데이터가 불균형한 상황에서 모델의 성능을 객관적으로 평가할 수 있는 지표는?', '특이도(Specificity)', '정확도(Accuracy)', 'F1-score', 'FPrate', 3, 'F1-score는 정밀도와 재현율의 조화평균으로, 클래스 불균형 상황에서도 모델 성능을 균형 있게 평가할 수 있다.', 100160, 'cbt'),
    (161, 3, '연관분석 지지도', '연관규칙분석에서 지지도(Support) 계산방식으로 옳은 것은?', 'A를 포함하는 거래 중 A와 B가 동시에 거래되는 비율', '전체 거래 중 A와 B가 동시에 포함된 거래 비율', 'A가 구매되지 않았을 때 B의 구매확률', 'A가 구매되지 않았을 때 B의 구매확률에 비해, A가 구매되었을 때 B의 구매확률이 증가한 비율', 2, '지지도는 전체 거래 중 A와 B가 동시에 포함된 거래의 비율 P(A∩B)이다.', 100161, 'cbt'),
    (162, 3, '결측값 처리', "'이름'과 '성별'로 구성된 고객 데이터에서 이름·성별 변수가 독립적으로 각각 10%의 결측값을 가질 때, 이름 또는 성별 중 하나라도 결측값이 있는 데이터를 모두 삭제하면 전체 데이터 중 삭제되는 비중은?", '10%', '15%', '19%', '23%', 3, '둘 다 결측이 아닐 확률은 0.9×0.9=0.81이므로, 하나라도 결측인 비율은 1-0.81=0.19, 즉 19%이다.', 100162, 'cbt'),
    (163, 3, '군집분석', '두 군집이 합쳐졌을 때 군집 내 오차제곱합(SSE)이 가장 적게 증가하는 방향으로 병합되는 군집분석 연결법은?', '중심연결법', '완전연결법', '와드연결법', '평균연결법', 3, "와드연결법(Ward's method)은 군집 내 오차제곱합(SSE)의 증가가 최소가 되도록 군집을 병합하는 방법이다.", 100163, 'cbt'),
    (164, 3, '데이터마이닝', '데이터마이닝 기법에 대한 설명으로 적절하지 않은 것은?', '반응변수가 주어지지 않은 상태에서 데이터 자체의 결합이나 유사성을 토대로 숨겨진 구조를 찾아내는 기법으로 k-means 군집분석이 활용될 수 있다.', '의사결정나무는 결과에 대한 이유를 설명하기 어렵기 때문에 화이트박스 모형으로 분류된다.', '인공신경망(ANN)은 입력층, 은닉층, 출력층으로 구성되며 복잡한 비선형관계를 파악하는 데 유용하다.', "연관규칙분석은 항목 간의 '만약~하면, ~하다'라는 형태의 관계를 발견하는 기법으로 장바구니분석이라고도 한다.", 2, '의사결정나무는 분류 과정과 기준을 시각적으로 쉽게 설명할 수 있어 화이트박스 모형으로 분류되며, 설명이 어렵다는 진술 자체가 모순이다.', 100164, 'cbt'),
    (165, 3, '연관분석 신뢰도', '품목 구매건수가 A=100, B=50, C=150, A·C=150, A·D=50, A·B·C=200, A·B·C·D=100, B·C·D=100건일 때, 연관규칙 A→B의 신뢰도는?', '40%', '50%', '60%', '65%', 2, 'A와 B를 모두 포함한 거래는 A·B·C(200)+A·B·C·D(100)=300건, A를 포함한 전체 거래는 100+150+50+200+100=600건이므로 신뢰도=300/600=0.5(50%)이다.', 100165, 'cbt'),
    (166, 3, '향상도', '향상도(Lift)에 대한 설명으로 적절한 것은?', "향상도는 'A와 B가 각각 독립적으로 일어날 확률의 곱'을 'A와 B가 동시에 일어날 확률'로 나누어 계산된다.", '향상도가 1보다 크면 해당 규칙은 양의 상관성을 가진다.', '향상도가 0일 때, 두 거래 품목 간에는 상관성이 없다.', '향상도가 0보다 작을 때, 음의 상관성을 가진다.', 2, '향상도(Lift) = P(A∩B)/(P(A)×P(B))이며, 값이 1보다 크면 A와 B가 양의 상관관계를 가진다는 뜻이다.', 100166, 'cbt'),
    (167, 3, '이상값', '이상값(Outlier)에 대한 설명으로 옳지 않은 것은?', '이상값은 입력오류, 측정오류, 표본추출오차 등 다양한 원인으로 발생할 수 있다.', '이상값은 일반적으로 데이터 전처리 단계에서 탐색하고 처리한다.', '사분위수범위(IQR)나 상자그림(Box plot), 산점도 등을 이용해 이상값을 판별할 수 있다.', '이상값은 분석결과를 왜곡하므로 발견되면 반드시 모두 제거해야 한다.', 4, '이상값이 실제 의미 있는 값일 수도 있으므로, 무조건 제거하기보다 원인을 파악해 대체·유지 등을 판단해야 한다.', 100167, 'cbt'),
    (168, 3, '확률분포', '확률 및 확률분포에 대한 설명 중 옳지 않은 것은?', '배반사건(서로소)인 두 사건은 독립사건이 아닐 수 있다.', '독립사건인 두 사건은 배반사건이 아닐 수 있다.', '연속확률분포에서 확률밀도함수(PDF)의 함숫값은 항상 0과 1 사이의 값을 갖는다.', '이산확률분포에서 확률질량함수(PMF)의 함숫값은 0과 1 사이의 값을 갖는다.', 3, '연속확률분포의 확률밀도함수(PDF) 값은 1보다 클 수도 있으며, 전체 구간에 대한 적분값만 1이 된다.', 100168, 'cbt'),
    (169, 3, '시계열 정상성', '시계열의 정상성(Stationarity)에 대한 설명으로 옳지 않은 것은?', '시계열 데이터의 각 관측값은 서로 독립이다.', '평균이 모든 시점에서 일정하다.', '분산이 모든 시점에서 일정하다.', '공분산은 특정 시점에 의존하지 않고 시차(time lag)에만 의존한다.', 1, '정상성은 평균·분산·공분산 구조가 시간에 따라 일정함을 의미할 뿐, 관측값들이 서로 독립임을 의미하지는 않는다(자기상관이 존재할 수 있다).', 100169, 'cbt'),
    (170, 3, '거리 측정', '맨해튼거리와 유클리디안거리에 대한 설명으로 옳지 않은 것은?', '맨해튼거리는 항상 유클리디안거리보다 작거나 같다.', '유클리디안거리는 두 점을 잇는 직선(최단) 거리이다.', '맨해튼거리는 각 차원(좌표) 차이의 절댓값을 모두 더한 값이다.', '맨해튼거리는 격자(바둑판) 형태의 경로를 따라 이동한 거리와 같다.', 1, '맨해튼거리는 격자 경로를 따라가므로 직선 최단거리인 유클리디안거리보다 항상 크거나 같다.', 100170, 'cbt'),
    (171, 3, '불순도', '어떤 노드에 속한 데이터 10개가 모두 하나의 클래스에만 속할 때(완전히 순수할 때), 이 노드의 지니지수와 엔트로피를 순서대로 바르게 나타낸 것은?', '1, 1', '1, 0', '0, 1', '0, 0', 4, '완전히 순수한 노드는 불순도가 없으므로 지니지수와 엔트로피 모두 0이다.', 100171, 'cbt'),
    (172, 3, '분류모형', '다음 중 분류(Classification) 모형에 해당하지 않는 것은?', '다중회귀분석', '인공신경망', '의사결정나무', '로지스틱회귀분석', 1, '다중회귀분석은 연속형 값을 예측하는 회귀 모형이며, 나머지는 분류에도 사용되는 모형이다.', 100172, 'cbt'),
    (173, 3, '다차원척도법', '다차원척도법(MDS)에 대한 설명으로 옳지 않은 것은?', '개체들 간의 거리(유사성)를 바탕으로 개체를 저차원 공간에 시각화한다.', '계량적 MDS는 비율척도나 구간척도로 측정된 데이터를 이용한다.', '비계량적 MDS는 순서척도로 측정된 데이터를 이용한다.', '개체 간 비유사성을 기준으로 동질적인 그룹(군집)을 형성하는 것이 목적이다.', 4, 'MDS의 목적은 개체 간 거리 구조를 저차원에 시각화하는 것이며, 그룹(군집)을 형성하는 것은 군집분석의 목적이다.', 100173, 'cbt'),
    (174, 3, 'SVM', '서포트벡터머신(SVM)에 대한 설명으로 옳지 않은 것은?', '두 클래스 사이의 마진(margin)을 최대화하는 초평면(hyperplane)을 찾아 분류한다.', '서포트벡터는 결정경계(초평면)에 가장 가까이 위치한 데이터 포인트이다.', '커널함수는 고차원 데이터를 저차원으로 변환하여 계산을 단순화하는 역할을 한다.', '선형으로 분리되지 않는 데이터도 커널 기법을 이용하면 분류할 수 있다.', 3, '커널함수(커널 트릭)는 저차원 데이터를 고차원 공간으로 매핑해 선형분리가 가능하도록 만드는 역할을 한다.', 100174, 'cbt'),
    (175, 3, '왜도', '변수 x를 y = ax + b (단, a > 0)로 선형변환했을 때, 다음 통계량 중 그 값이 변하지 않는 것은?', '왜도(Skewness)', '표준편차', '평균', '중앙값', 1, '양의 계수(a>0)로 선형변환하면 분포의 모양(비대칭 정도)은 변하지 않으므로 왜도는 그대로 유지된다.', 100175, 'cbt'),
    (176, 3, '이상치 판정', '사분위수와 사분위범위(IQR)를 이용한 이상치 판정에 대한 설명으로 틀린 것은?', 'IQR은 제3사분위수(Q3)에서 제1사분위수(Q1)를 뺀 값이다.', '이상치의 하한 경계는 Q1 - 1.5×IQR, 상한 경계는 Q3 + 1.5×IQR이다.', '이상치는 Q1 + 1.5×IQR보다 작거나 Q3 - 1.5×IQR보다 큰 값으로 판정한다.', '제2사분위수(Q2)는 데이터의 중앙값(median)과 같다.', 3, '이상치는 Q1 - 1.5×IQR보다 작거나 Q3 + 1.5×IQR보다 큰 값으로 판정하며, 부호가 반대로 서술된 설명이 틀렸다.', 100176, 'cbt'),
    (177, 3, '인공신경망', '인공신경망에서 각 층의 노드 수는 줄이고 은닉층의 수는 늘렸을 때 나타날 수 있는 현상으로 가장 적절한 것은?', '모델 구조가 전체적으로 단순해진다.', '모델의 학습 시간이 짧아진다.', '역전파 과정에서 기울기 소실(vanishing gradient) 문제가 발생할 수 있다.', '표현할 수 있는 함수의 복잡도가 감소한다.', 3, '은닉층이 깊어질수록 역전파 시 기울기가 여러 층을 거치며 점점 작아지는 기울기 소실 문제가 발생하기 쉽다.', 100177, 'cbt'),
    (178, 3, '상관계수', '두 변수 x와 y의 상관계수가 0.2일 때, 2x+1과 -y-1의 상관계수는?', '-0.2', '0.2', '0.4', '-0.4', 1, '선형변환에서 계수의 부호만 상관계수의 부호에 영향을 준다. x에는 양수(2)를, y에는 음수(-1)를 곱한 것과 같으므로 부호가 반대로 바뀌어 상관계수는 -0.2가 된다.', 100178, 'cbt'),
    (179, 3, '회귀분석', '회귀모형에 대한 설명으로 옳지 않은 것은?', '회귀계수는 일반적으로 최소제곱법(OLS)으로 추정한다.', '모형의 설명력은 -1에서 1 사이의 값을 갖는 결정계수(R²)로 평가한다.', '잔차분석을 통해 정규성·등분산성 등 모형의 가정을 점검한다.', '결정계수(R²)가 1에 가까울수록 모형의 설명력이 높다.', 2, '결정계수(R²)는 일반적으로 0에서 1 사이의 값을 가지며, -1에서 1 사이라는 설명은 틀렸다.', 100179, 'cbt'),
    (180, 3, '의사결정나무', '의사결정나무에서 마디(노드)를 분리하는 기준에 대한 설명으로 적절하지 않은 것은?', '카이제곱통계량의 p-value가 작아지는 방향으로 분리한다.', '지니지수(Gini Index)가 최대가 되는 방향으로 분리한다.', '엔트로피 지수가 작아지는 방향으로 분리한다.', '분산 감소량이 커지는 방향으로 분리한다.', 2, '노드 분리는 불순도(지니지수·엔트로피)가 최소가 되는 방향으로 이루어지며, 지니지수를 최대화하는 방향이 아니다.', 100180, 'cbt'),
    (181, 3, '표본추출', '표본추출방법에 대한 설명으로 틀린 것은?', '계통추출법은 첫 표본을 무작위로 정한 뒤 일정한 간격으로 표본을 추출한다.', '층화추출법은 모집단을 동질적인 여러 집단(층)으로 나눈 후 각 층에서 표본을 추출한다.', '집락(군집)추출법은 각 집락의 내부가 동질적이도록 구성하여 추출한다.', '단순무작위추출법은 모든 표본이 뽑힐 확률이 동일하도록 임의로 추출한다.', 3, '집락추출법은 집락 내부는 모집단과 유사하게 이질적으로 구성하고, 집락 간에는 동질적이 되도록 나눈 뒤 일부 집락을 통째로 추출하는 방법이다.', 100181, 'cbt'),
    (182, 3, '상자그림', "수면제를 복용한 20명의 '수면시간 증가량'을 상자그림으로 요약한 결과, 최댓값 4.0시간·중앙값 1.2시간 등이 확인되었다. 상자그림 해석으로 옳지 않은 것은?", '수면시간 증가량의 최댓값은 4.0시간이다.', '적어도 절반(50%)의 사람은 수면시간이 1.2시간 이상 증가했다.', '일부 사람은 수면시간이 오히려 감소(증가량이 음수)하였다.', '정확히 5명의 수면시간이 감소하였다.', 4, '상자그림은 사분위수 등 분포의 개형만 보여줄 뿐, 특정 조건을 만족하는 정확한 인원 수까지는 알려주지 않는다.', 100182, 'cbt'),
    (183, 3, '앙상블', '앙상블(Ensemble) 학습에 대한 설명으로 옳은 것은?', '앙상블은 하나의 단일 모형만을 정교하게 학습시켜 성능을 높이는 방법이다.', '배깅(Bagging)과 부스팅(Boosting)은 대표적인 앙상블 기법이다.', '랜덤포레스트는 앙상블이 아닌 단일 의사결정나무 모형이다.', '앙상블 모형은 항상 개별 모형보다 결과 해석이 쉽다.', 2, '여러 모형을 결합해 성능을 높이는 배깅과 부스팅은 대표적인 앙상블 기법이다.', 100183, 'cbt'),
    (184, 3, '결측값 처리', '결측값(Missing Value) 처리에 대한 설명으로 옳지 않은 것은?', '완전분석법(Complete Case)은 결측값이 포함된 행(케이스)을 제거하고 분석한다.', '평균대치법은 결측값을 해당 변수의 평균값으로 채워 넣는다.', '단순대치법은 결측값을 하나의 추정치로 대체하는 방법이다.', '완전분석법은 결측값을 평균으로 대치하여 모든 데이터를 그대로 활용하는 방법이다.', 4, '완전분석법은 결측값이 있는 케이스를 제거하는 방법이며, 평균으로 대치해 모든 데이터를 활용하는 것은 평균대치법에 대한 설명이다.', 100184, 'cbt'),
    (185, 3, '가설검정', '가설검정에 대한 설명으로 옳지 않은 것은?', "귀무가설(H0)은 일반적으로 '차이가 없다' 또는 '효과가 없다'를 의미하는 기본 가설이다.", '유의수준(α)은 귀무가설이 참인데도 기각하는 제1종 오류의 허용확률이다.', '대립가설(H1)은 연구자가 주장하거나 입증하고자 하는 가설이다.', 'p-value가 유의수준보다 크면(높으면) 귀무가설을 기각한다.', 4, 'p-value가 유의수준보다 작을 때 귀무가설을 기각하며, 유의수준보다 클 때는 귀무가설을 기각하지 못한다.', 100185, 'cbt'),
    (186, 3, '표본오차', '표본오차와 비표본오차에 대한 설명으로 옳지 않은 것은?', '표본오차는 표본이 모집단을 완전히 대표하지 못해 발생하는 오차이다.', '일반적으로 표본 크기를 늘리면 표본오차는 줄어드는 경향이 있다.', '비표본오차는 조사·입력·집계 과정의 실수 등으로 발생하는 오차이다.', '비표본오차는 표본 크기를 늘릴수록 함께 줄어든다.', 4, '비표본오차는 조사 과정의 실수 등에서 비롯되므로, 표본 크기를 늘린다고 해서 줄어드는 것이 아니다.', 100186, 'cbt'),
    (187, 3, '불순도', '의사결정나무와 불순도(impurity) 지표에 대한 설명으로 옳지 않은 것은?', '엔트로피와 지니지수는 노드의 불순도를 측정하는 지표이다.', '좋은 분리는 지니지수가 최대가 되는 방향으로 이루어진다.', '정보이득(Information Gain)은 분리 전후 엔트로피의 감소량으로 정의된다.', '지니지수는 0에 가까울수록 노드가 순수(pure)하다.', 2, '좋은 분리는 지니지수(불순도)가 최소가 되는 방향으로 이루어지며, 최대화하는 방향이 아니다.', 100187, 'cbt'),
    (188, 3, '연관분석', "'기저귀→맥주' 연관규칙에서 지지도가 0.4, 향상도가 약 1.33일 때, 이 규칙에 대한 설명으로 옳지 않은 것은?", '지지도(support)는 0.4이다.', '향상도(lift)는 약 1.33으로 1보다 크다.', '신뢰도(confidence)는 약 0.34이다.', '향상도가 1보다 크므로 두 품목은 서로 함께 구매되는 경향(양의 연관)이 있다.', 3, '신뢰도는 지지도(0.4)에 향상도(1.33)를 곱한 B의 지지도 관계로 계산되며, 주어진 조건에서 약 0.34가 아니라 다른 값으로 계산되어 이 설명이 옳지 않다.', 100188, 'cbt'),
    (189, 3, '연관분석 지지도', "전체 거래 10건 중 품목 A를 포함한 거래는 7건, 품목 B를 포함한 거래는 6건이며, A와 B를 동시에 포함한 거래는 5건일 때, 연관규칙 'A→B'의 지지도(support)는?", '0.7', '0.6', '0.5', '0.71', 3, '지지도 = P(A∩B) = 5/10 = 0.5이다.', 100189, 'cbt'),
]
